import type { DistractorMap } from "./index";

const percyJacksonDistractors: DistractorMap = {
  "pj-01-ch-01": [
    ["Percy's class goes on a field trip to the Museum of Natural History in New York City, where they are supposed to sketch dinosaur skeletons for a science project, though Percy mostly just wanders around bored.", "Percy's class goes on a field trip to a large science and space museum in Manhattan, where they're supposed to learn about rockets and constellations, though Percy can barely focus on any of it."],
    ["Mrs. Dodds trips and tumbles down the museum's grand marble staircase near the Greek urns exhibit, badly spraining her ankle on the last step, and has to be rushed by ambulance to a hospital six blocks away while the whole class looks on in stunned shock.", "Mrs. Dodds accidentally gets locked inside a sealed exhibit room when an old door malfunctions during the tour, and museum security has to force the rusty lock open to finally free her twenty minutes later."],
    ["Mr. Brunner grabs a dusty bronze shield hanging near the Greek and Roman wing and hurls it across the gallery to Percy, who barely manages to catch it in time to block Mrs. Dodds's first strike.", "Mr. Brunner tosses Percy the polished wooden cane he sometimes uses to steady his wheelchair, and Percy swings it wildly at Mrs. Dodds, though the flimsy cane barely slows her down at all."],
    ["Everyone in the class remembers Mrs. Dodds clearly and even asks Percy why she stormed off so suddenly during the actual field trip, but the nervous chaperones exchange worried glances and refuse to explain what actually happened to her afterward.", "Everyone assumes Percy invented the whole story about a monster attack just to get out of trouble again, since he already has a well-known reputation at Yancy Academy for exaggerating and telling wild, made-up stories."],
    ["Percy actually feels excited and unusually confident about the upcoming trip because pre-algebra is one of the few school subjects he's genuinely good at, and he's secretly hoping to impress Mrs. Dodds with a sharp, well-rehearsed answer during the tour.", "Percy feels proud and a little smug walking into the museum because he's technically the top-scoring student in his entire grade this term, a rare bright spot in an otherwise rough and complicated school year at Yancy."],
  ],
  "pj-01-ch-02": [
    ["Percy overhears Grover and Mr. Brunner excitedly planning what sounds like a surprise birthday party for him, whispering eagerly about cake flavors, party games, and which classmates from Yancy Academy to secretly invite without him ever noticing.", "Percy overhears Grover and Mr. Brunner arguing heatedly about his poor grades in Latin class, with Mr. Brunner insisting Percy needs to study much harder before the end of the year or risk failing entirely."],
    ["Percy is formally expelled after getting into a shoving match with Nancy Bobofit right in the crowded cafeteria, and the headmaster tells him flatly not to bother coming back in the fall semester at all.", "Percy asks to leave school early on his own, telling Mr. Brunner tearfully that he misses his mom too much to finish out the last few weeks of the term at Yancy, a detail Percy only pieces together three days later back at camp."],
    ["Grover admits that the school secretly pays him a small monthly stipend to keep an eye on troublemaking students, and Percy just happened to be his latest assignment this year.", "Grover admits he's actually failing every single one of his difficult classes just like Percy, and he's been dreading having to tell his worried family about it all year long."],
    ["The three old women wave Percy and Grover over near the fruit stand and offer them a free bag of ripe apples and a ride the rest of the way home in their rusty car, which Grover politely refuses without much explanation, a fact that Chiron confirms later that same week over dinner.", "The three old women shout out a warning that the bus is about to break down somewhere on the highway, though the driver behind the wheel ignores them completely and keeps driving anyway, which happens just past the old stone archway near the strawberry fields."],
    ["Percy feels relieved because Grover finally sits him down at the very back of the bus and calmly explains everything that's been secretly going on, patiently answering every single question Percy has.", "Percy feels bored during the long, uneventful ride since nothing unusual happens at all, and he mostly just stares out the window thinking quietly about summer vacation plans."],
  ],
  "pj-01-ch-03": [
    ["Sally surprises Percy with a long drive far upstate to visit his grandparents' old, creaky farmhouse, hoping a change of scenery and some fresh country air will finally cheer him up after such a rough year at school, something Luke mentions only once, in passing, by the campfire that night.", "Sally packs up all the camping gear and takes Percy deep into the mountains for a quiet weekend of hiking, fishing, and stargazing, far away from Gabe's temper and the noise of the city, right around the same time the conch horn sounds for evening assembly."],
    ["Percy dreams that Mrs. Dodds is chasing him endlessly through the museum's dark hallways, her claws just inches from grabbing his shoulder as the lights flicker overhead.", "Percy dreams that he wins a big schoolwide pre-algebra competition, standing proudly on a stage while his classmates and teachers applaud him loudly."],
    ["Gabe unexpectedly shows up at the cabin late at night, banging on the door and demanding that Sally and Percy pack up and come home with him immediately.", "Two police officers arrive at the cabin asking careful questions about the museum incident, wanting to know exactly what happened to Mrs. Dodds that day."],
    ["Percy notices that Grover is wearing a bulky plaster cast on one entire leg, apparently from a bad fall down a steep flight of stairs, and wonders privately when that could have possibly happened to him, something that takes nearly twenty minutes longer than anyone expects.", "Percy notices that Grover has piled on several extra layers of baggy, mismatched clothing despite the sweltering summer heat, which strikes him as a strange and oddly hurried thing to do, a detail that later shows up in the report Chiron sends to Olympus."],
    ["Sally laughs off Grover's frantic warning at first, telling him gently to calm down and stop being so dramatic about a little bad weather rolling in off the coast, which happens close enough to the Big House that half the camp notices.", "Sally calls Gabe from the cabin's old landline phone, asking him to drive out and pick them up himself instead of getting behind the wheel in the storm, something Annabeth writes down carefully in her battered notebook afterward."],
  ],
  "pj-01-ch-04": [
    ["Grover explains that he's actually a runaway prince from a small, war-torn foreign kingdom overseas, sent secretly into hiding after a violent rebellion overthrew his entire royal family years ago, a fact that surprises even the older campers who thought they'd seen everything.", "Grover explains that Mr. Brunner is secretly a retired government spy who has been quietly protecting Percy on a long-term assignment for years without Percy ever knowing, right as the last of the evening light fades over the cabins."],
    ["A giant serpent with several hissing, venomous heads bursts violently out of the dark woods and attacks the wrecked car, snapping hungrily at the windows with each of its many mouths at once.", "A pack of enormous wild wolves surrounds the wrecked car from every side, snarling and circling closer and closer as Percy desperately tries to figure out how to protect his mom and Grover, a detail nobody thinks to question again until much later that summer, something that costs them nearly an extra hour they can't really spare."],
    ["She is knocked unconscious by a heavy, glancing blow from the charging monster, and Percy has to drag her limp body the rest of the long, exhausting way up the hill to safety, a fact Percy doesn't fully understand until Chiron explains it properly.", "She hides inside the wrecked car, ducking low below the dashboard, until the monster eventually loses interest in her entirely and wanders off slowly into the dark trees, which several campers swear they saw with their own eyes from the porch."],
    ["Percy lures the Minotaur back into the wrecked, smoking car and slams the heavy door shut just as the leaking engine catches fire and violently explodes right behind him, a detail that ends up mattering a lot more than anyone realizes at the time.", "Percy distracts the Minotaur by flashing a light directly in its eyes over and over again until the confused, snorting creature stumbles backward off a nearby rocky cliff, something that leaves even Grover more rattled than usual for the rest of the day."],
    ["Percy thinks he sees his mother waving cheerfully to him from inside a car driving slowly away down the hill, though he's far too dizzy and disoriented from the fight to be sure, a detail Percy only pieces together three days later back at camp.", "Percy sees what looks like a group of police officers rushing quickly up the hill toward him with flashlights, though everything around him is blurry and rapidly fading fast, something that happens right around four-thirty in the afternoon, according to Annabeth's watch."],
  ],
  "pj-01-ch-05": [
    ["Percy wakes up groggy in a hospital bed somewhere in New York City, hooked up to beeping machines with no memory of how he got there. A nurse tells him he's been unconscious for nearly two days after some kind of car accident.", "Percy wakes up back in his own bedroom at his mom's apartment, half-convinced the whole ordeal with the Minotaur was just a bad dream. He can hear Gabe's poker game going on in the living room, which almost makes the last few days feel normal again."],
    ["Grover feeds him plain hospital chicken soup and a whole stack of dry saltine crackers from a rolling cart, telling him it's the best the cafeteria downstairs could possibly offer that day.", "Grover makes him swallow a spoonful of strange, bitter medicine that tastes like old gym socks, promising in a hushed, urgent voice that it will help him recover much faster."],
    ["Percy meets Clarisse and Luke sitting together at a table playing a rowdy card game, teasing each other loudly the whole time while barely noticing Percy shuffle quietly into the room, which happens just past the old stone archway near the strawberry fields.", "Percy meets his mother and a man introduced simply as Grover's uncle sitting together at a card table, both of them acting strangely calm given everything that has just happened, a detail Grover brings up again weeks later, still looking uneasy about it."],
    ["Mr. D reveals that he used to be Percy's father's closest friend decades ago, back before some bitter falling-out over an old, forgotten grudge drove the two of them apart.", "Mr. D reveals that he is actually Grover's long-lost uncle from his mother's side of the family, which is apparently why Grover has been so nervous around him all morning."],
    ["Mr. Brunner reveals that he is actually a retired soldier who once fought bravely in a war overseas, which explains the old, faded scars Percy had noticed earlier on his forearms, right around the same time the conch horn sounds for evening assembly.", "Mr. Brunner reveals that he can turn completely invisible whenever he concentrates hard enough, demonstrating by briefly vanishing right out of his wheelchair in front of a stunned Percy, a fact Mr. D grumbles about for days afterward to anyone who'll listen, something that takes nearly twenty minutes longer than anyone expects."],
  ],
  "pj-01-ch-06": [
    ["Chiron leads Percy through a hidden underground library stacked floor to ceiling with ancient weapons, dusty scrolls, and cracked stone tablets, most of which Percy can't even begin to read or translate.", "Chiron shows Percy a long, dripping underground tunnel that supposedly leads all the way down to the ocean floor, though he refuses to say who originally built it or why it's there, a detail that later shows up in the report Chiron sends to Olympus, which happens close enough to the Big House that half the camp notices."],
    ["Percy ends up in Cabin Eleven simply because it's the only cabin left with an empty bunk by the time he finally arrives late at camp that evening, something Annabeth writes down carefully in her battered notebook afterward.", "Percy is assigned to Cabin Eleven as a kind of informal punishment for arriving at camp so late in the summer season, or so Luke jokingly tells him, a fact that surprises even the older campers who thought they'd seen everything."],
    ["Clarisse succeeds in dunking Percy's head deep into the toilet bowl, and the whole cabin bursts out laughing loudly while Percy sputters and drips toilet water on the bathroom floor, right as the last of the evening light fades over the cabins.", "Percy fights back hard enough that a real scuffle breaks out between the two of them, and both he and Clarisse end up dragged off together to see Chiron for punishment afterward, a detail nobody thinks to question again until much later that summer."],
    ["Clarisse is actually Chiron's own daughter, which is apparently why she gets away with bullying newer campers without much real consequence at all. Even Mr. D seems oddly reluctant to punish her.", "Clarisse turns out to be from Cabin Eleven too, technically Percy's very own cabinmate, which makes the awkward toilet encounter feel even more uncomfortable and strange afterward."],
    ["Annabeth tells Percy she wants to be his personal training partner for sword fighting, convinced he has real hidden potential after witnessing the whole bathroom incident, a fact Percy doesn't fully understand until Chiron explains it properly.", "Annabeth tells Percy she wants his help investigating a strange, worsening problem with the camp's boundary magic, which she's noticed has been acting up more and more lately, which several campers swear they saw with their own eyes from the porch."],
  ],
  "pj-01-ch-07": [
    ["Annabeth tells Percy that both of her parents are completely ordinary mortals from Virginia, and that she only ended up at camp because a school counselor happened to recommend it to her family.", "Annabeth tells Percy that her father is actually a decorated war general stationed overseas for many years, which is part of why she so rarely ever gets to see him, a detail that ends up mattering a lot more than anyone realizes at the time, something that leaves even Grover more rattled than usual for the rest of the day."],
    ["Annabeth reveals that a camper was recently caught red-handed stealing gold drachmas from the camp's treasury vault, and everyone has been quietly on edge about it ever since, a detail Percy only pieces together three days later back at camp.", "Annabeth reveals that Mr. D's ceremonial throne was accidentally destroyed in a small kitchen fire during a dinner mishap last week, and he's been in a foul mood ever since, something that happens right around four-thirty in the afternoon, according to Annabeth's watch."],
    ["Luke tells Percy that he's actually never once been allowed to go on a real quest of his own, no matter how many times he's respectfully asked Chiron for permission, a fact that Chiron confirms later that same week over dinner.", "Luke tells Percy that his quest a couple of years back was actually a huge success, and that he came back proudly with treasure, glory, and new respect from the camp, which happens just past the old stone archway near the strawberry fields."],
    ["Campers write short, heartfelt letters to their godly parents and mail them through a special overnight delivery service run quietly by the busy Hermes cabin campers, a detail Grover brings up again weeks later, still looking uneasy about it.", "Campers stand together and sing a short hymn in ancient Greek before every single meal, a tradition Percy fumbles his way through without understanding a single word of it, something Luke mentions only once, in passing, by the campfire that night."],
    ["Mr. D surprises everyone by giving a warm, heartfelt speech welcoming Percy to camp, even raising a glass of Diet Coke high in his honor in front of the assembled campers, right around the same time the conch horn sounds for evening assembly.", "Mr. D refuses to acknowledge Percy at all during the entire dinner, acting as though the new camper standing right in front of him at the table simply doesn't exist, a fact Mr. D grumbles about for days afterward to anyone who'll listen, something that takes nearly twenty minutes longer than anyone expects."],
  ],
  "pj-01-ch-08": [
    ["Grover tells Percy that the Big Three gods stopped speaking to each other entirely centuries ago after a bitter, ongoing argument over who should rightfully rule Olympus's throne, a detail that later shows up in the report Chiron sends to Olympus.", "Grover tells Percy that the Big Three gods are actually half-brothers of Chiron himself, part of an old, complicated, and deeply tangled family tree of ancient immortals, which happens close enough to the Big House that half the camp notices."],
    ["Percy is captured and tied up by Clarisse's group, and he has to wait until Annabeth's team storms in to cut him loose. It's an embarrassing end to his part of the game, and Clarisse doesn't let him forget it for days.", "Percy loses the fight badly, getting knocked flat by the electrified spear and forced to sit out the rest of the game. He limps to the sidelines feeling humiliated, sure that everyone watched him get beaten so easily."],
    ["A buzzing swarm of giant, angry hornets suddenly attacks the players scattered through the dark woods, forcing everyone to scramble desperately for cover in the middle of the game.", "A pack of snarling wild wolves suddenly bursts out of the trees near the flag, interrupting the game just as one team is about to score the winning, game-ending point."],
    ["A glowing lightning bolt crackles loudly into the air above Percy's head, and campers gasp aloud, whispering nervously that he must surely be a true son of Zeus, a fact that surprises even the older campers who thought they'd seen everything.", "A glowing silver owl shimmers softly into view above Percy's head, and several campers immediately assume out loud that he must be one of Athena's own children, right as the last of the evening light fades over the cabins."],
    ["Clarisse's team manages to snatch the flag despite all the surrounding chaos, dragging it back across the creek even as Clarisse limps badly from her fight with Percy, a detail nobody thinks to question again until much later that summer.", "Percy personally grabs the flag himself right after being publicly claimed, carrying it proudly back across the creek to a stunned, wide-eyed round of applause from everyone, something that costs them nearly an extra hour they can't really spare."],
  ],
  "pj-01-ch-09": [
    ["Percy is moved into Cabin Three as a punishment assigned by Chiron for the chaos he caused with the bathroom incident earlier in the summer. He's told he'll stay there in isolation until Mr. D decides he's learned his lesson.", "Percy asks to be moved out of Cabin Eleven himself, admitting to Chiron that he and Luke have been butting heads too much to share a cabin. Chiron reluctantly agrees, though he warns Percy that cabin transfers are almost never actually granted."],
    ["They tell him that Camp Half-Blood's funding from Olympus has completely dried up and the camp is at serious risk of running out of money by the following winter. Chiron looks genuinely worried as he explains how few golden drachmas remain in the treasury vault.", "They tell him that Chiron's extended centaur family has mysteriously gone missing somewhere out west near the Rocky Mountains, and Chiron has been quietly worried sick about them for weeks, a fact Percy doesn't fully understand until Chiron explains it properly."],
    ["Percy is led to a small stone temple hidden deep within the strawberry fields, where a flickering, hologram-like image of Apollo himself delivers his prophecy in riddles.", "Percy is taken down through a creaking trapdoor to a hidden cave beneath the dining pavilion, where torches flicker on the walls and a raspy voice echoes from the darkness."],
    ["The prophecy tells Percy that he is destined to become the next ruler of Olympus once the current gods eventually step aside. Percy finds the idea almost impossible to believe, especially coming from such a strange, wheezing voice.", "The prophecy tells Percy that he must never leave the safety of camp again, or disaster will surely follow him wherever he goes. It leaves him wondering how he could possibly go on a quest if leaving camp is forbidden."],
    ["Percy refuses the quest outright, telling Chiron quite plainly that he doesn't feel ready yet, and asking that an older, more experienced camper be sent in his place instead, a detail that ends up mattering a lot more than anyone realizes at the time.", "Percy asks Chiron for a few more days to think everything over carefully before deciding, wanting some quiet time to process everything he's just learned about the prophecy, something that leaves even Grover more rattled than usual for the rest of the day."],
  ],
  "pj-01-ch-10": [
    ["Percy chooses Clarisse and Luke to accompany him on the dangerous quest, figuring their combat experience will make up for how little he personally trusts either of them.", "Percy decides to go completely alone on the entire quest, insisting firmly to Chiron that he doesn't want to risk getting any of his friends hurt because of him, a detail Percy only pieces together three days later back at camp."],
    ["Percy receives a full suit of gleaming golden armor along with a small chariot pulled by two mechanical rams for the journey. Chiron warns him the chariot is loud and conspicuous, better suited for battle than for sneaking across the country.", "Percy receives an enchanted map that supposedly shows exactly where the stolen lightning bolt is hidden somewhere out west, though Chiron admits with a shrug that the old map might be badly outdated by now."],
    ["Clarisse secretly follows the group and boards the very same Greyhound bus a few stops later, insisting loudly that she wants to help even though nobody actually invited her along, something that happens right around four-thirty in the afternoon, according to Annabeth's watch.", "A group of persistent reporters somehow recognizes Percy from the evening news and boards the bus hoping to get an exclusive interview about the strange museum incident, a fact that Chiron confirms later that same week over dinner, which happens just past the old stone archway near the strawberry fields."],
    ["Percy takes the invisibility cap for himself and slips out quietly through the emergency exit alone, leaving Annabeth and Grover behind to fend for themselves.", "Percy hands the invisibility cap over to Grover instead, insisting firmly that Grover use it to escape while Percy and Annabeth stay behind to cover him."],
    ["The bus simply sputters to a stop on the gravel shoulder of the highway and refuses to start again, stranding absolutely everyone on board, including the furious Furies.", "The panicked bus driver swerves hard off the road and crashes straight into a ditch trying to escape the chaos of the fight breaking out in the back of the bus, something Luke mentions only once, in passing, by the campfire that night."],
  ],
  "pj-01-ch-11": [
    ["The garden gnome statues scattered around the shop are all oddly dressed in tiny Camp Half-Blood t-shirts and matching caps, which strikes Annabeth as a strange and tacky gift-shop gimmick at first, right around the same time the conch horn sounds for evening assembly.", "The garden gnome statues turn out to be cleverly disguised robots that Aunty Em uses to greet and entertain customers browsing the roadside shop. Annabeth still finds them deeply unsettling, even after Aunty Em cheerfully explains they're harmless decorations."],
    ["Grover recognizes a statue among the gnomes as his own long-lost mother, a satyr who vanished years ago while desperately searching for the lost god Pan.", "Grover recognizes what looks like a statue of Chiron himself among the gnomes, which terrifies him into thinking their old mentor is truly gone. He nearly breaks down sobbing until Annabeth points out the statue's face is slightly wrong around the eyes."],
    ["Aunty Em turns out to be one of the three Furies wearing a clever disguise, sent specifically to trap Percy and his friends before they can continue their quest.", "Aunty Em turns out to be Clarisse's own mother wearing a disguise, running the roadside shop as a side business while secretly keeping tabs on her daughter's rivals."],
    ["Percy simply closes his eyes tight and swings his sword blindly in Medusa's general direction, somehow landing the fatal killing blow through sheer dumb luck alone, a fact Mr. D grumbles about for days afterward to anyone who'll listen.", "Percy scoops up a handful of loose gravel from the shop floor and throws it hard directly into Medusa's face to blind her just long enough to land his attack, something that takes nearly twenty minutes longer than anyone expects."],
    ["Percy digs a deep hole behind the shop's cracked parking lot and buries Medusa's head there, hoping no one will ever be foolish enough to come dig it back up again, a detail that later shows up in the report Chiron sends to Olympus.", "Percy wraps Medusa's head carefully in an old beach towel and decides to keep it as a trophy to show off proudly once they finally make it back to camp, which happens close enough to the Big House that half the camp notices, something Annabeth writes down carefully in her battered notebook afterward."],
  ],
  "pj-01-ch-12": [
    ["Grover pulls out a small magic whistle that Chiron secretly gave him back at camp and blows a silent note that somehow lets him understand exactly what the lost poodle wants.", "Grover reads the poodle's mind using a simple mind-reading spell that Annabeth secretly taught him back at camp, concentrating hard on its jumbled little thoughts."],
    ["The wealthy family insists on giving them an old, rusted car instead of cash as a generous reward, which turns out to be far more trouble than it's actually worth once it quickly breaks down, right as the last of the evening light fades over the cabins.", "The grateful poodle, in return, leads them straight to a hidden spot where the stolen lightning bolt is supposedly buried deep underground. They dig for nearly an hour before realizing the poodle was just chasing an old buried bone the whole time."],
    ["Percy notices a small newspaper article announcing that his stepfather Gabe has recently been arrested for an unrelated, illegal gambling scheme back in the city, a detail nobody thinks to question again until much later that summer.", "Percy notices an article about an upcoming reunion event at Yancy Academy, which makes him feel oddly homesick for a school he was so recently kicked out of, something that costs them nearly an extra hour they can't really spare."],
    ["Percy spots what looks like a group of satyrs playing pipes and dancing together in a golden wheat field as the train rushes past. He presses his face to the glass, but they vanish into the stalks before he can point them out to Grover.", "Percy glimpses an enormous eagle swooping down and carrying off what looks like a full-grown sheep from a nearby farm. The whole scene passes in seconds, and by the time Annabeth looks up, the sky is already empty again."],
    ["Percy thinks for a moment that he sees Clarisse's scowling face reflected in the dark train window, even though she's supposed to be back at camp training hard, a fact Percy doesn't fully understand until Chiron explains it properly.", "Percy glimpses a shadowy figure standing near the tracks that looks unsettlingly like Luke, though the speeding train rushes past before he can be entirely sure of it, which several campers swear they saw with their own eyes from the porch, a detail that ends up mattering a lot more than anyone realizes at the time."],
  ],
  "pj-01-ch-13": [
    ["Annabeth insists on detouring to a famous art museum in downtown St. Louis, wanting to see a specific traveling collection of ancient Greek pottery on display there, something that leaves even Grover more rattled than usual for the rest of the day.", "Annabeth insists on stopping instead at a public library nearby that's supposedly hosting a rare weekend exhibit of ancient Greek artifacts, coins, and old scrolls, a detail Percy only pieces together three days later back at camp, something that happens right around four-thirty in the afternoon, according to Annabeth's watch."],
    ["Percy is left alone at the top with a chatty tour guide and a bored park ranger, both of whom seem completely ordinary and harmless at first glance.", "Percy is left alone at the top with two mysterious teenagers about his own age, who keep exchanging strange, knowing glances with each other the whole time."],
    ["The woman turns out to be one of the Furies wearing yet another clever disguise, apparently still relentlessly hunting Percy even after their earlier fight on the bus, a fact that Chiron confirms later that same week over dinner.", "The woman turns out to be Medusa's vengeful twin sister, seeking bitter revenge for what Percy did to her sibling back at the roadside garden gnome shop, which happens just past the old stone archway near the strawberry fields, a detail Grover brings up again weeks later, still looking uneasy about it."],
    ["Percy's sword suddenly turns back into a harmless ballpoint pen right in the middle of the desperate fight, leaving him fumbling anxiously to uncap it again, something Luke mentions only once, in passing, by the campfire that night.", "Percy accidentally drops his sword down the observation deck's open elevator shaft while frantically dodging a blast of fire from the furious, snarling Chimera, right around the same time the conch horn sounds for evening assembly."],
    ["Echidna dares Percy to fight the monstrous Chimera completely bare-handed, taunting him that a real son of Poseidon wouldn't ever need a weapon at all, a fact Mr. D grumbles about for days afterward to anyone who'll listen.", "Echidna dares Percy to hand over Annabeth's invisibility cap as a show of surrender, falsely promising to let all three of the friends go free in exchange, something that takes nearly twenty minutes longer than anyone expects, a detail that later shows up in the report Chiron sends to Olympus."],
  ],
  "pj-01-ch-14": [
    ["Percy gets swept far downstream by the powerful, churning current and has to swim exhausted for what feels like hours before finally dragging himself up onto the muddy riverbank, which happens close enough to the Big House that half the camp notices.", "Percy loses consciousness the moment he hits the cold water and wakes up sometime later sprawled on the riverbank, unsure how he even got there. Grover has to shake him awake and explain everything that happened, since Percy can't remember any of it at all."],
    ["Percy meets his father, Poseidon, in person underwater in a coral throne room, and the sea god personally reassures him that his mother's situation will be resolved soon, though he warns Percy the road ahead is far from over.", "Percy meets a talking dolphin who guides him gently back toward shore, chattering the whole way about how rare it is to meet a demigod. The dolphin even offers to introduce him to some sea nymphs before Percy insists he really needs to get moving."],
    ["News reports simply state that the Gateway Arch has been closed for routine repairs after some unspecified structural damage. There's no mention of Percy at all, which almost makes him relax until Annabeth points out that's exactly what worries her.", "News reports actually praise Percy as a hero, claiming he bravely helped several frightened tourists escape safely down the smoky stairwell during the chaos near the top of the Gateway Arch, something Annabeth writes down carefully in her battered notebook afterward."],
    ["A curious catfish swims up out of the murky river water and drops Percy's sword right at his feet, almost as if delivering it on purpose from somewhere far downstream.", "Percy has to spend some of his precious remaining drachmas to buy a plain new sword from a cramped pawn shop once he finally reaches the muddy shore, a fact that surprises even the older campers who thought they'd seen everything."],
    ["They decide to head straight back to New York City right away, worried enough about Percy's mother that continuing the quest suddenly feels far less urgent, right as the last of the evening light fades over the cabins.", "They decide to lie low in St. Louis for a few extra days instead, hoping the news coverage about the Arch will quietly die down before they move on, a detail nobody thinks to question again until much later that summer."],
  ],
  "pj-01-ch-15": [
    ["Grover writes a quick letter and drops it in a mailbox right outside the diner, trusting regular postal mail to somehow reach Chiron back at camp in time, something that costs them nearly an extra hour they can't really spare.", "Grover borrows a stranger's cell phone right outside the busy diner and calls Chiron directly, speaking in hushed, urgent tones about the danger ahead, a fact Percy doesn't fully understand until Chiron explains it properly."],
    ["A kind waitress at the diner quietly covers their bill herself, telling them softly that she recognizes hungry kids when she sees them and waves off any thanks.", "Annabeth insists on paying with a stash of golden drachmas she'd saved from camp, though the confused cashier has absolutely no idea what to do with them."],
    ["The stranger turns out to be Luke's own father in disguise, quietly and secretly tracking down news of his estranged son by keeping tabs on Percy's quest.", "The stranger turns out to be Dionysus disguised in a leather jacket, checking up on Percy's progress out of grudging obligation to Chiron back at camp."],
    ["Ares offers to personally fight Percy's remaining battles for the rest of the entire quest himself, promising smugly that it would make everything much easier for him, something that leaves even Grover more rattled than usual for the rest of the day.", "Ares offers to reveal exactly who really stole Zeus's master lightning bolt right then and there, if Percy simply agrees to do him one small favor first, a detail Percy only pieces together three days later back at camp, something that happens right around four-thirty in the afternoon, according to Annabeth's watch."],
    ["The shield turns out to be guarded by an actual, snarling hellhound chained up tightly behind the water slides, ready to attack anyone foolish enough to get close to the rusted old fence around it.", "The shield simply isn't where Ares said it would be, and they find nothing but an empty, dusty pedestal in its place. Annabeth suspects immediately that someone must have beaten them to it, or that Ares lied about where he left it."],
  ],
  "pj-01-ch-16": [
    ["Ares gives Percy a magical shield that he claims can never be broken, saying Percy will need it more than he will for the rest of the quest. Percy finds it heavy and awkward to carry, but he figures it's rude to turn down a gift from a god of war, a fact that Chiron confirms later that same week over dinner.", "Ares gives Percy a folded, hand-drawn map that supposedly shows exactly where the stolen lightning bolt is hidden somewhere out west, though he flatly refuses to explain how he ever got hold of it, which happens just past the old stone archway near the strawberry fields."],
    ["Percy quietly writes down the truck's license plate number on his hand and reports the mistreated animals to the local police instead of taking any risky action himself right there on the street, a detail Grover brings up again weeks later, still looking uneasy about it.", "Percy manages to calm the animals down and convinces them to stay put in the truck until animal control can arrive to help. It takes patience and a surprising amount of talking, but eventually the zebra stops kicking at the trailer walls."],
    ["A friendly doorman leads them to a modest, free motel meant for stranded travelers passing quietly through Vegas, offering them a small room for the night, something Luke mentions only once, in passing, by the campfire that night.", "A mysterious doorman leads them instead to a quiet back room upstairs, claiming that Chiron himself is waiting there to meet with them in secret, right around the same time the conch horn sounds for evening assembly."],
    ["Percy realizes with a sudden chill that the casino is secretly run by distant relatives of Medusa herself, and that the staff have been quietly watching them the entire time they've been inside, a fact Mr. D grumbles about for days afterward to anyone who'll listen.", "Percy realizes the unlimited credit card the doorman gave him earlier is actually completely fake and simply won't work at all once he tries to use it outside the casino doors, something that takes nearly twenty minutes longer than anyone expects, a detail that later shows up in the report Chiron sends to Olympus."],
    ["They rush out because casino security suddenly starts chasing after them, accusing the three of secretly cheating at the card tables and demanding they leave at once, which happens close enough to the Big House that half the camp notices.", "They rush out in a sudden panic because Clarisse unexpectedly shows up right at the casino entrance, and none of them want to have to explain themselves to her, something Annabeth writes down carefully in her battered notebook afterward."],
  ],
  "pj-01-ch-17": [
    ["The waterbed store turns out to be run by a disguised version of Ares, apparently moonlighting as a salesman between quests of his own. He greets them with a wink, as if he's been expecting Percy to show up eventually.", "The waterbed store is run by what seems like a perfectly ordinary, overly enthusiastic salesman with no connection to Greek myth at all. He talks their ears off about thread counts and warranty plans until Annabeth finally cuts him off."],
    ["Crusty simply tries to sell them a plain waterbed at an outrageously inflated price, refusing to budge an inch even when Annabeth tries very hard to haggle him down at the front counter, right as the last of the evening light fades over the cabins.", "Crusty locks Annabeth and Grover in a back storage room while he tries to pressure Percy into signing a suspicious sales contract. Percy can hear them pounding on the door, and he realizes he has only moments to figure out what's really going on."],
    ["Percy manages to talk Crusty down through calm, patient negotiation at the counter, convincing him that letting his friends go free is the smarter business decision.", "Percy simply grabs his friends and outruns Crusty straight out the front door, leaving the confused salesman shouting angrily after them in the parking lot."],
    ["Percy finds a hidden map tucked behind Crusty's cluttered desk drawer that seems to show a secret shortcut leading all the way back to Camp Half-Blood, something that costs them nearly an extra hour they can't really spare.", "Percy finds a half-burned letter revealing that Ares himself was actually the one who originally stole Zeus's master lightning bolt from Mount Olympus, a fact Percy doesn't fully understand until Chiron explains it properly, which several campers swear they saw with their own eyes from the porch."],
    ["It means they could technically head straight home right away without ever finishing the difficult quest at all, though none of the three seriously consider giving up on it now, a detail that ends up mattering a lot more than anyone realizes at the time.", "It means, according to Annabeth's excited theory, that they no longer need to worry about the missing lightning bolt at all. Percy isn't so sure her theory actually holds up once he thinks it through more carefully on the drive, something that leaves even Grover more rattled than usual for the rest of the day."],
  ],
  "pj-01-ch-18": [
    ["The Nereid gives Percy a gleaming new sword from the depths, telling him firmly that his old one won't be strong enough for what waits ahead in the Underworld.", "The Nereid gives Percy a shimmering silver map that supposedly leads straight to his father Poseidon's grand underwater palace somewhere far beneath the waves."],
    ["They end up fighting Charon in a tense sword duel right at the riverbank, barely managing to slip past him afterward. Charon curses them the whole time, threatening to report the incident to Hades personally, something that happens right around four-thirty in the afternoon, according to Annabeth's watch.", "They sneak past Charon entirely using Annabeth's invisibility cap, holding their breath and tiptoeing carefully the whole time so the suspicious ferryman won't hear a single footstep, a fact that Chiron confirms later that same week over dinner."],
    ["Cerberus flatly refuses to let anyone through no matter what they try or say, planting all three of his massive, drooling heads in the doorway and growling loudly at every approach, which happens just past the old stone archway near the strawberry fields.", "Cerberus breaks free of his chain and chases them all the way back toward the entrance, forcing them to sprint desperately for the ferry dock. They barely make it back across the river before all three heads come snapping through the gate."],
    ["Annabeth sings a soft lullaby that puts all three of Cerberus's heads to sleep almost instantly, letting them tiptoe past. Percy is amazed at how easily her calm, steady voice manages to work where brute force never could.", "Annabeth offers Cerberus a chunk of raw meat, and once he's distracted gnawing on it, he loses interest in them entirely. Percy is relieved, though he wonders where exactly Annabeth got a chunk of raw meat in the first place."],
    ["They almost turn back right there at the entrance, seriously debating out loud whether the risk of continuing further into the Underworld is even worth it, a detail Grover brings up again weeks later, still looking uneasy about it.", "They decide to wait at the entrance a while longer instead, half-hoping that Chiron might somehow catch up and join them for the rest of the dangerous journey, something Luke mentions only once, in passing, by the campfire that night."],
  ],
  "pj-01-ch-19": [
    ["Hades furiously accuses Percy of secretly freeing souls from the Underworld, claiming the balance of the dead has been thrown into chaos. He paces angrily in front of his throne, insisting Percy will pay dearly for the disruption.", "Hades furiously accuses Percy of scheming to steal his throne, insisting that Poseidon must have sent him to challenge his rule. He glares at Percy with pure venom, certain the whole visit is part of some larger plot against him."],
    ["Percy is stunned to find Hades's actual helm of darkness hidden inside his own backpack, tucked beneath his spare clothes, though he has absolutely no memory of ever putting it there himself.", "Percy finds a folded letter from Luke tucked inside his backpack, warning him cryptically not to trust anyone at camp. Percy stares at the handwriting, trying to figure out when Luke could possibly have slipped it in there."],
    ["It reveals, once Hades checks his own vault, conclusively that Luke was the one who stole both items and planted them himself. Hades seems almost satisfied to finally have someone concrete to blame, though Percy isn't sure the evidence really proves it.", "It reveals, based on a symbol scorched into the backpack, that Ares definitely stole both items on his own for some unknown reason. Percy finds that hard to believe, since Ares never seemed interested in helms or lightning bolts before."],
    ["Hades threatens to turn Percy's mother into a permanent, wandering ghost trapped forever in the gray Fields of Asphodel unless Percy hands over the missing helm right away, right around the same time the conch horn sounds for evening assembly.", "Hades threatens to send Percy's mother to fight endlessly in the Underworld's brutal gladiator arena unless Percy quickly retrieves his stolen helm and returns it, a fact Mr. D grumbles about for days afterward to anyone who'll listen."],
    ["They escape by convincing Charon to ferry them back across the river one more time, paying him with the last of their drachmas. Charon grumbles about the extra trip but agrees once Annabeth throws in a few more coins.", "They escape through a secret tunnel that Annabeth spots behind Hades's throne, crawling through the dark until they reach open air. Percy has never been so relieved to see actual daylight again after crawling blind through the dirt."],
  ],
  "pj-01-ch-20": [
    ["The pearls carry them straight back to Camp Half-Blood's sandy beach, appearing right in the middle of the camp's quiet canoe lake just at dusk, something that takes nearly twenty minutes longer than anyone expects.", "The pearls carry them instead to the very top of the Empire State Building, right at the secret entrance leading up to Mount Olympus itself, a detail that later shows up in the report Chiron sends to Olympus."],
    ["Ares confesses that he actually stole the bolt on Zeus's own secret orders, all as a hidden loyalty test arranged specifically for Poseidon's new son. Percy can hardly believe Zeus would go to such extreme lengths just to test him, which happens close enough to the Big House that half the camp notices.", "Ares confesses that Chiron secretly helped plan the whole devious scheme from the very start, feeding him private information about Percy's quest the entire time behind everyone's unsuspecting back, something Annabeth writes down carefully in her battered notebook afterward."],
    ["Ares sends a snarling pack of hellhounds charging fast across the sandy beach at Percy, hoping to finish him off entirely before their duel even properly begins.", "Ares summons the very same fire-breathing Chimera from the Gateway Arch to attack Percy all over again, clearly hoping to finish what it had already started."],
    ["Percy defeats Ares by cleverly tricking him into charging straight into a hidden patch of quicksand right near the churning water's edge, right as the last of the evening light fades over the cabins.", "Percy defeats Ares by pulling out Medusa's severed head at the very last possible second and using its lingering gaze to turn him partially to stone, a detail nobody thinks to question again until much later that summer, something that costs them nearly an extra hour they can't really spare."],
    ["The tide slowly uncovers Zeus's master lightning bolt buried deep in the wet sand instead of the helm, and Percy realizes with a sudden jolt that he'll need to deliver it personally to Olympus himself, a fact Percy doesn't fully understand until Chiron explains it properly.", "Percy finds the helm but decides to bury it again himself, convinced it's safer left hidden than handed over to anyone, even the Furies. Annabeth argues fiercely with him about it, insisting Hades needs it back if they want any real hope of peace, which several campers swear they saw with their own eyes from the porch."],
  ],
  "pj-01-ch-21": [
    ["The manhunt is called off on a strange legal technicality once officials realize Percy recently turned eighteen and can no longer legally be listed as a missing minor at all, a detail that ends up mattering a lot more than anyone realizes at the time.", "The manhunt is called off after Ares, oddly enough, publicly confesses right to the police that he alone was behind the whole strange incident at the Gateway Arch, something that leaves even Grover more rattled than usual for the rest of the day, a detail Percy only pieces together three days later back at camp."],
    ["Percy sends Grover and Annabeth home ahead of him and decides to quit the entire quest, planning instead to simply mail the recovered bolt back to Olympus, something that happens right around four-thirty in the afternoon, according to Annabeth's watch.", "Percy insists that all three of them go together to see Zeus in person, feeling strongly that Annabeth and Grover deserve to fully share in finishing the quest, a fact that Chiron confirms later that same week over dinner."],
    ["Percy decides it's safest to mail the bolt back to Olympus using the Hermes Express delivery service, nervously tracking the package the entire way there himself, which happens just past the old stone archway near the strawberry fields.", "Percy meets Zeus back at Camp Half-Blood instead, where the powerful sky god descends briefly from the clouds to personally collect his recovered bolt, a detail Grover brings up again weeks later, still looking uneasy about it."],
    ["Percy suspects that Mr. D secretly orchestrated the whole plot from the start, using his boredom at camp as cover for something bigger. It's a wild theory, but Percy can't quite shake the feeling that Mr. D knows more than he lets on, something Luke mentions only once, in passing, by the campfire that night.", "Percy suspects that Chiron himself secretly orchestrated the whole plot, worried that his old mentor's loyalties aren't what they seem. He hates even thinking it, but too many small details keep nagging at him, right around the same time the conch horn sounds for evening assembly."],
    ["Poseidon tells Percy that his mother has decided to move permanently to Camp Half-Blood, so she can live closer to him and Chiron from now on, a fact Mr. D grumbles about for days afterward to anyone who'll listen.", "Poseidon tells Percy, gently and with some sadness, that his mother has unfortunately lost all her memories of him during her time trapped in the Underworld, something that takes nearly twenty minutes longer than anyone expects."],
  ],
  "pj-01-ch-22": [
    ["The camp holds a quiet, somber ceremony with no real celebration at all, since everyone is still visibly shaken by just how dangerous the quest turned out to be, a detail that later shows up in the report Chiron sends to Olympus.", "The camp actually reprimands Percy for taking so long to complete the whole quest, with Mr. D grumbling loudly that he cut it far too close to the solstice deadline, which happens close enough to the Big House that half the camp notices."],
    ["Luke reveals, to Percy's shock, that he is actually Percy's older half-brother, both of them sons of Poseidon without knowing it. Percy struggles to process the idea, since nothing about their fight ever felt like family loyalty.", "Luke reveals that he's decided to leave camp for good and live as an ordinary mortal, tired of being a demigod and fighting monsters. He tells Percy he just wants a normal life, far from Olympus and everything it demands of him."],
    ["Luke admits that it was actually his idea to tell Ares to hide his shield at Waterland in the first place, setting up that whole detour. He laughs bitterly, saying it was almost too easy to convince Ares to go along with the plan.", "Luke admits that he was the one who secretly tipped off Echidna about exactly where to find them at the top of the Gateway Arch. He says he'd been tracking their progress the entire time through a network of monsters loyal to Kronos."],
    ["Luke leaves Percy to be captured by camp security instead, tipping them off that Percy has been sneaking around after curfew. Percy spends an uncomfortable hour being questioned before Chiron finally sorts out what really happened.", "Luke leaves Percy stranded just outside the camp's magic borders, hoping some passing monster will finish the job for him. Percy has to fight off the cold and his own exhaustion just to make it back through the gates alive."],
    ["Poseidon explains that Kronos is actually Luke's real father, which is why Luke has always felt such a strange, restless pull toward the ancient Titan's cause ever since he was young. It's a claim that shakes Percy deeply, though Poseidon admits even he isn't entirely certain it's true.", "Poseidon explains that Kronos is actually a monster Percy already unknowingly defeated earlier on his quest, though its true form is far more dangerous. Poseidon warns that what Percy fought was likely only a fragment of the Titan's full, terrifying power."],
  ],
  "pj-02-ch-01": [
    ["Percy dreams that he's back on Half-Blood Hill fighting the Minotaur all over again, the fight replaying exactly as it happened the summer before.", "Percy dreams that Annabeth is trapped somewhere deep inside a maze, calling out for help while a dragon paces just outside her reach."],
    ["In the dream, Grover whispers Percy's name over and over in a panicked voice, as though trying to reach him across a great distance.", "In the dream, Grover whispers that Camp Half-Blood has already been destroyed, which leaves Percy shaken even after he wakes up."],
    ["It's the day of Percy's final exam in his Ancient Greek mythology elective, a subject he's actually pretty good at for once.", "It's actually the first day at a brand new school Percy just transferred to, and he's nervously hoping to make a better first impression this time."],
    ["Percy has actually been attacked by monsters constantly all year, worse than any year before, leaving him exhausted and always on guard.", "Percy has actually already been expelled once already this year, and this school is a last-chance placement his mom fought hard to get him into."],
    ["The monster spots Grover's reflection in a store window and charges straight through the glass after him, sending shoppers screaming.", "The monster follows a trail of enchanted acorns that Grover accidentally spills from his pocket while running, leading it straight to him."],
  ],
  "pj-02-ch-02": [
    ["They face a team of ghostly warriors summoned by Luke, translucent figures that swing their dodgeballs with unnerving, silent precision.", "They face off against Clarisse's cabin in what starts as a rough but ordinary prank battle before things take a stranger turn."],
    ["The dodgeballs are frozen rock-solid, hard enough that a direct hit can knock a player out cold on the spot.", "The dodgeballs are coated in a strange poison that puts anyone they hit into a deep, sudden sleep right on the gym floor."],
    ["Tyson pulls out a cell phone and calls camp counselors for backup, though it takes several confusing minutes to explain where they are.", "Tyson waves around a magic wand he says he found earlier that day, though nobody's quite sure where it actually came from."],
    ["Annabeth tells Percy that Chiron has quit being a teacher for good, packing up and leaving camp without any explanation.", "Annabeth tells Percy that his mother has apparently been kidnapped, which is the real reason she rushed to find him."],
    ["They are rescued at the last second by a flying chariot sent down by Zeus, swooping in to pluck them away from the giants.", "A gym teacher steps in and somehow scares the giants away with nothing more than a stern whistle and a raised eyebrow."],
  ],
  "pj-02-ch-03": [
    ["They call in a favor from a friendly satyr who happens to have an old pickup truck, offering to drive them as far as camp.", "They flag down a subway conductor who claims to know secret shortcuts through the tunnels straight to Camp Half-Blood."],
    ["The taxi can apparently only drive in reverse the entire trip, which somehow doesn't slow the sisters down at all.", "The taxi randomly seems to teleport them to the wrong cities entirely, forcing the sisters to backtrack furiously each time."],
    ["Each sister wears a special magic contact lens that copies whatever the shared eye sees, so technically all three can watch the road.", "The sisters mostly use the eye to check their makeup in the mirror, seemingly steering the taxi from memory instead."],
    ["Percy has to hand over a whole bag of golden drachmas up front before the sisters will even agree to answer a single question.", "Percy has to solve a tricky riddle the sisters pose before they'll even unlock the car doors to let them in."],
    ["The taxi's engine sputters out halfway there, stranding them in an unfamiliar forest miles from camp.", "The taxi accidentally overshoots and drops them off at the entrance to Olympus instead of anywhere near camp."],
  ],
  "pj-02-ch-04": [
    ["They find camp completely abandoned, with cabins empty and not a single camper or satyr in sight anywhere.", "They find camp has been hastily rebuilt as a walled fortress, with barricades and watchtowers replacing the usual cabins."],
    ["Tyson turns out to be a surprisingly gifted musician, humming low notes that seem to calm even the most agitated camp animals.", "Tyson turns out to be an expert swimmer who apparently never needs to come up for air, staying underwater for what seems like hours."],
    ["Every camper immediately treats Tyson like a celebrity, crowding around to ask him questions and take turns showing him the cabins.", "The campers largely ignore Tyson completely, never speaking to him directly even when he's standing right in the middle of the group."],
    ["Percy feels completely thrilled about Tyson tagging along and can't help bragging about him to anyone who'll listen.", "Percy feels mostly bored by the whole situation and privately wishes people would stop asking him questions about Tyson."],
    ["The worry going around camp is that supplies are running dangerously low and there won't be enough food to last through the summer.", "The worry is that Chiron himself is quietly planning to shut the camp down for good, tired of dealing with the constant danger."],
  ],
  "pj-02-ch-05": [
    ["Tyson is revealed to be a son of Hephaestus who ran away from his father's forge after an accident that left him afraid of hammers.", "Tyson is revealed to be an ordinary mortal orphan with no godly parent at all, just an unusually large and gentle kid who wandered into camp."],
    ["Percy feels proud right away, immediately introducing Tyson to every camper as his new brother without a second thought.", "Percy feels almost nothing about the announcement, since he claims he'd already figured out the truth about Tyson weeks earlier."],
    ["Tyson is given his own brand-new private cabin, hastily built just for Cyclopes, separate from the regular cabin rows.", "Tyson is sent instead to live out in the woods with the resident satyrs, since there's no official cabin for Cyclopes yet."],
    ["Chiron has apparently retired happily, packing his things to travel the world now that he feels his teaching days are behind him.", "Chiron has actually been promoted, surprisingly, to help run daily affairs up on Mount Olympus alongside the gods."],
    ["A sudden budget cut from Olympus has forced camp to power down several of its magical defenses to save resources.", "The gods have apparently decided, for reasons no one at camp understands, to deliberately remove camp's magical protection."],
  ],
  "pj-02-ch-06": [
    ["Tantalus revives an old sword-fighting tournament from years past, and it's during one of the early matches that the real trouble breaks out.", "Tantalus starts an odd new cooking competition among the cabins, and it's during the judging that monsters crash the event."],
    ["A swarm of giant metal wasps suddenly descends on the chariots mid-race, their stingers sparking against the wooden frames.", "A flock of shrieking harpies swoops down on the dining pavilion during the race, snatching food right off the tables."],
    ["Tantalus surprisingly praises Percy, Annabeth, and Tyson for defending the camp so bravely, even offering them extra dessert that night.", "Tantalus panics and cancels the chariot races permanently, declaring the whole tradition too dangerous to ever bring back. Campers grumble about it for days, certain he's just looking for an excuse to avoid dealing with the birds again."],
    ["Percy grabs a garden hose and sprays the birds relentlessly until they finally give up and scatter off into the woods.", "Percy tricks the birds into chasing after Tantalus instead, waving a pastry to lure them toward him and away from the campers."],
    ["It shows, oddly enough, that camp feels safer and happier than ever under Tantalus, at least according to his own frequent announcements.", "It shows, in a bizarre twist campers whisper about, that the birds may have secretly been working for Chiron all along. Nobody can quite explain the rumor, but it spreads through the cabins within a day."],
  ],
  "pj-02-ch-07": [
    ["The god Apollo visits Percy disguised as a chatty school bus driver, humming cheerful tunes the whole ride before revealing himself.", "The goddess Hera visits Percy disguised as a stern camp lunch lady, ladling out soup while dropping cryptic hints between servings."],
    ["Hermes seems mostly worried about losing his job as messenger god, complaining that Olympus has been cutting back his responsibilities.", "Hermes seems oddly fixated on a package he lost somewhere in the mortal world, insisting it needs to be found before summer's end."],
    ["Hermes asks Percy to hunt down Luke and bring him straight back to Olympus to face judgment for his betrayal.", "Hermes asks Percy, bitterly, to simply forget Luke ever existed and stop mentioning his name around camp."],
    ["Hermes leaves behind a gleaming suit of golden armor, though it turns out to be a size too big for Percy to wear comfortably.", "Hermes leaves behind an intricate map that supposedly marks the location of every monster currently active in the world."],
    ["Percy feels mostly bored through the conversation and quietly wishes Hermes would wrap things up so he can get back to training.", "Percy feels irritated that Hermes interrupted his sword-training session just to talk about family problems Percy can't really help with."],
  ],
  "pj-02-ch-08": [
    ["The Princess Andromeda turns out to be the name of Poseidon's grand underwater palace, hidden deep beneath the waves.", "The Princess Andromeda is actually a transport ship that Chiron quietly runs to ferry supplies and campers between camp and the mainland."],
    ["They board because they've supposedly been officially invited to a peace summit that Luke is hosting aboard the ship.", "They board simply because it's the only ferry currently available heading toward the general direction of the Fleece's island."],
    ["Grover has actually been given the official quest to find the Golden Fleece, surprising everyone since satyrs rarely lead quests.", "Annabeth has been given the official quest to find the Golden Fleece, which frustrates Percy since he wanted to volunteer himself."],
    ["They're handed VIP boarding passes and simply walk aboard disguised as an ordinary family of tourists checking in for a cruise.", "They fly directly onto the ship's upper deck using a pair of borrowed winged sandals Hermes had left them."],
    ["The ship feels surprisingly festive at first, with cheerful music playing and passengers lounging by the pool like an ordinary vacation cruise.", "The ship feels completely empty and abandoned as they sneak aboard, with no crew or passengers anywhere in sight."],
  ],
  "pj-02-ch-09": [
    ["They overhear a chilling conversation revealing that Grover has already been captured and is being held somewhere aboard the ship.", "They overhear a conversation suggesting that Clarisse has secretly been feeding information to Luke this whole time."],
    ["A locked cage sits in the corner of the room, holding several campers Luke has apparently kidnapped from camp over recent months.", "One entire wall is covered in detailed maps marking every weak point in Camp Half-Blood's defenses, clearly used for planning an attack."],
    ["Luke admits that Kronos personally ordered him to kidnap Annabeth's mother, Athena, as part of a larger scheme against Olympus. Percy is horrified, though Luke seems almost proud of how far the plan has already come.", "Luke admits that he was actually the one who cursed Chiron long ago, trapping him as camp's teacher forever out of old resentment. He says he's never regretted it, even after everything Chiron has done for other campers since."],
    ["Luke unexpectedly bursts into tears, admitting quietly that he misses his father Hermes terribly despite everything that's happened.", "Luke says he'd actually agree to stop his plans entirely if Hermes would just apologize to him properly, face to face."],
    ["They manage to convince Luke's crew to let them leave peacefully by boat, surprising everyone given how tense the confrontation had been.", "They use Percy's growing water powers to swim the entire way back to shore almost instantly, barely getting wet in the process."],
  ],
  "pj-02-ch-10": [
    ["They are rescued, unexpectedly, by a modern Coast Guard cutter that happens to be patrolling the area at exactly the right moment.", "They are rescued by an old-fashioned pirate ship crewed by living sailors who seem thrilled to have found castaways to bring aboard."],
    ["The ghostly crew immediately surrounds them and tries to throw them back overboard, insisting no living passengers are allowed on their ship.", "The ghostly crew begs Percy right away to free them from whatever curse has kept them sailing these waters since the Civil War."],
    ["The ship, to their surprise, takes them straight back to Camp Half-Blood immediately, cutting their journey dramatically short.", "The ship turns out to be another trap secretly set by Luke, who apparently arranged for it to intercept them after their escape."],
    ["The ship is surprisingly loud and modern, full of blaring music and flashing lights that seem completely out of place for a ghost ship.", "The ship is bright and cheerful, strangely decorated as if for an ongoing party the ghostly crew never stopped celebrating."],
    ["They feel completely relaxed aboard the ghost ship, treating the whole strange situation like just another ordinary cruise vacation.", "They feel immediately hostile toward the ghostly crew and try to pick a fight before realizing the spirits mean them no harm."],
  ],
  "pj-02-ch-11": [
    ["They encounter a rival ship crewed entirely by the Hunters of Artemis, who eye them warily as the two vessels pass close together.", "They encounter what looks like an ancient Roman legion's warship, oars rowing in perfect unison as it cuts through the water nearby."],
    ["Clarisse's ship is threatened by a giant kraken that Kronos has apparently summoned specifically to sink her and end the quest early.", "Clarisse's ship is threatened by an army of sea nymphs loyal to Luke, who surround the hull trying to drag it down."],
    ["Clarisse's ship, against all odds, makes it through the deadly strait completely undamaged, its crew cheering as they clear the danger.", "Clarisse's ship is boarded and captured fully intact by Luke's forces, who tow it away with the crew still aboard."],
    ["Clarisse panics completely, abandoning her post and hiding below deck for the entire length of the dangerous passage.", "Clarisse abandons her crew entirely, grabbing the nearest lifeboat to save herself first as the ship starts to break apart."],
    ["Percy and his friends are captured alongside Clarisse, all of them hauled aboard the same enemy vessel as prisoners.", "Percy and his friends manage to pull Clarisse from the wreckage themselves, and the group continues on together from that point."],
  ],
  "pj-02-ch-12": [
    ["They wash up directly on Polyphemus's island, stumbling straight into the Cyclops's territory before they even know where they are.", "They wash up, confusingly, on a beach that looks exactly like the shore near Camp Half-Blood, though something feels off about it."],
    ["Circe secretly turns male visitors into golden statues, displaying them as decorative pieces scattered throughout her spa's garden.", "Circe secretly puts male visitors into an endless magical sleep, laying them out on lounge chairs where they never wake up."],
    ["Percy resists Circe's magic completely, feeling only a brief tingling sensation before shaking it off entirely.", "Percy is transformed into a small, twittering bird instead of a guinea pig, and finds himself trapped in a gilded cage."],
    ["Annabeth immediately sees through Circe's tricks and confronts her directly, refusing to be fooled by the spa's luxurious facade.", "Annabeth is locked in a cage the moment they arrive, held as a hostage to make sure Percy and Tyson cooperate."],
    ["Percy stays trapped as a guinea pig for the rest of the book, forcing Tyson and Annabeth to carry him along in a small cage.", "Percy is rescued only because Clarisse happens to arrive just in time, breaking Circe's spell with a well-timed threat."],
  ],
  "pj-02-ch-13": [
    ["Annabeth seems completely unaffected by the whole ordeal, brushing it off and eager to press on with the quest right away.", "Annabeth has apparently lost her memory entirely, unable to recall Percy, Tyson, or anything about the quest they've been on."],
    ["Annabeth tries to steal a small boat from the shore, planning to sail back and confront Luke on his own ship alone.", "Annabeth tries to fly all the way home using a pair of borrowed winged sandals, despite having no idea which direction camp actually is."],
    ["Percy lets Annabeth go without saying a word, figuring she needs space and trusting she'll find her own way back eventually.", "Percy orders Tyson to physically grab Annabeth and drag her back to shore by force, which only makes her angrier."],
    ["Annabeth seems mostly worried that her mother Athena has abandoned her forever, given how little contact she's had since arriving at camp.", "Annabeth seems mostly worried that she's about to be kicked out of camp for good after everything that's gone wrong on this quest."],
    ["They seriously discuss giving up the quest entirely and heading straight back home, exhausted from everything that's happened so far.", "They decide, after a tense argument, to split up permanently and continue the rest of the quest separately from one another."],
  ],
  "pj-02-ch-14": [
    ["They find a massive, coiled dragon guarding the Golden Fleece, its scales glinting in the same golden light as the treasure itself.", "They find Luke himself standing guard over the Golden Fleece, apparently having beaten them to the island first."],
    ["The sheep can apparently talk, calling out warnings to intruders about hidden traps scattered around Polyphemus's pen.", "The sheep breathe small bursts of fire whenever strangers get too close, which makes sneaking past the flock especially tricky."],
    ["Percy discovers Chiron himself trapped on the island, apparently kidnapped weeks earlier and disguised to avoid Polyphemus's suspicion.", "Percy discovers Clarisse trapped on the island too, having been captured after her own ship wrecked nearby days earlier."],
    ["Polyphemus believes Grover, still in disguise, is actually a spy sent by Poseidon to steal his prized flock of sheep.", "Polyphemus believes Grover, in disguise, is a runaway slave who escaped from a neighboring island and needs to be punished."],
    ["They charge straight at Polyphemus without any real plan, hoping sheer surprise will be enough to catch him off guard.", "They immediately step out of hiding and demand that Polyphemus hand over the Fleece, banking on intimidation to work in their favor."],
  ],
  "pj-02-ch-15": [
    ["Tyson explains that Poseidon himself personally rescued him from the ocean floor right after the ghost ship went down.", "Tyson explains that Clarisse's crew actually picked him up after the wreck and kept him hidden safely below deck."],
    ["Tyson followed a trail of golden drachmas that Annabeth had apparently dropped along the shoreline without realizing it.", "Tyson was guided the whole way by a message from Chiron sent through an Iris-message, pointing him toward the island."],
    ["Percy carries Annabeth away from the island immediately, deciding it's too risky to use the Fleece's magic before they're somewhere safe.", "Percy calls out to Poseidon, asking his father to heal Annabeth directly instead of risking the Fleece's untested magic."],
    ["Percy convinces Polyphemus that Tyson is actually a ghost, hoping the superstitious Cyclops will be too frightened to attack him.", "Percy convinces Polyphemus that the Fleece was actually stolen by Luke earlier that same day, hoping to redirect his fury."],
    ["They accidentally kill Polyphemus in the struggle, and the island falls eerily silent once the Cyclops finally stops moving.", "Polyphemus surrenders peacefully once he's overpowered, even waving politely as their ship sails calmly away from the island."],
  ],
  "pj-02-ch-16": [
    ["They cling to floating wreckage for hours until a passing fishing boat finally spots them and hauls them aboard.", "They are pulled mysteriously to shore by a lingering trace of Circe's magic, still somehow attached to Percy from their earlier encounter."],
    ["A pod of friendly dolphins, apparently sent by Poseidon, carries them safely through the water toward the nearest shore.", "Luke's own crew unexpectedly rescues them out of guilt, hauling them aboard a small boat despite orders to leave them behind."],
    ["They wash up, remarkably, right on Camp Half-Blood's own beach, saving them what would have been a long trip back.", "They wash up on a small, deserted island that doesn't appear on any map, with no clue which direction to go from there."],
    ["Annabeth realizes with horror that they've accidentally left the Golden Fleece behind on the sunken ship at the bottom of the sea.", "Annabeth realizes that Tyson is missing again, having apparently wandered off somewhere along the unfamiliar beach."],
    ["They must return the Fleece within a month's time or risk losing Poseidon's favor for good, according to what Annabeth remembers.", "They must find Chiron before sunrise or camp will officially be shut down, according to a deadline Tantalus supposedly set."],
  ],
  "pj-02-ch-17": [
    ["They realize with alarm that they only have about one hour before the incoming tide floods the entire stretch of beach they're standing on.", "They realize, from a garbled Iris-message, that Camp Half-Blood may have already been destroyed sometime while they were away."],
    ["Clarisse refuses to speak to them at all, storming off angrily down the beach without another word. Percy can tell she's furious about how the quest ended up, and he doesn't blame her one bit.", "Clarisse immediately hands over the Fleece without any argument, seemingly relieved to be rid of the responsibility. She admits quietly that carrying something so powerful had made her more nervous than she wanted to say."],
    ["Percy decides to keep the Fleece and deliver it himself, wanting the credit for finishing what was technically Clarisse's quest.", "Percy decides to hide the Fleece somewhere safe on the beach until the whole group can travel back to camp together."],
    ["Annabeth pays for the flight using a stash of golden drachmas she'd been carefully saving the entire trip, hoping the airline will accept them.", "They somehow convince the airline counter agent to let Clarisse fly for free, using a mix of charm and a made-up sob story."],
    ["A group of Hunters of Artemis suddenly surrounds them on the beach, mistaking the exhausted travelers for monsters at first glance.", "A hurricane suddenly sweeps in off the coast, scattering everyone across the beach and forcing them to take shelter separately."],
  ],
  "pj-02-ch-18": [
    ["Percy refuses to fight at all, begging Luke for mercy and hoping to stall long enough for a rescue to arrive.", "Percy hides below deck, keeping quiet and waiting for a rescue instead of confronting Luke directly. He tells himself it's the smart move, even though part of him feels like he's letting his friends down."],
    ["A squad of camp counselors dramatically arrives by helicopter, rappelling down onto the deck to join the fight. It's a dramatic rescue that catches everyone, including Luke's own soldiers, completely off guard.", "Artemis and her Hunters arrive dramatically to join the fight, firing arrows down onto the deck from the ship's railings."],
    ["Chiron explains that Grover led him straight there using their empathy link, sensing exactly where Percy and the others were in danger.", "Chiron explains that he simply got lucky, spotting the Princess Andromeda from shore through an old pair of binoculars."],
    ["Tyson hides below deck for most of the fighting, only coming out once the noise of battle has completely died down.", "Tyson tries at first to make peace with Luke's soldiers, offering to shake hands before realizing they have no interest in talking."],
    ["Chiron reveals that he used to be Luke's secret private teacher years before Luke ever arrived at camp. He admits he still feels partly responsible for how things eventually went wrong between them.", "Chiron reveals that he is actually immortal because of an old curse Zeus placed on him centuries ago, unrelated to any Titan bloodline."],
  ],
  "pj-02-ch-19": [
    ["They arrive to find the tree already fully healed, apparently by Chiron himself using some old centaur magic before they got there.", "They arrive just moments too late, finding the tree already withered and dead despite their best efforts to hurry back."],
    ["Chiron announces, to everyone's surprise, that camp is cancelling all activities for the rest of the summer out of caution.", "Chiron announces, oddly, that Tantalus himself will be personally racing in the upcoming chariot competition."],
    ["Percy teams up with Clarisse this time, the two of them setting aside their rivalry to build the fastest chariot at camp.", "Percy competes completely alone this time, insisting he doesn't need any teammates to win the race."],
    ["Tyson builds an entire chariot rigged to fly a few feet off the ground, giving their team a startling advantage on the track.", "Tyson builds a set of completely invisible wheels that make no sound at all, baffling the other teams during the race."],
    ["Percy's team crashes hard on the final turn, sputtering across the finish line dead last to everyone's disappointment.", "Clarisse's team ends up winning the race instead, edging out Percy and Annabeth by a narrow margin at the final stretch."],
  ],
  "pj-02-ch-20": [
    ["The tree's magic makes it grow so enormous that it becomes a genuine structural threat to several nearby cabins.", "The tree's magic accidentally spreads for miles, healing every plant across the whole state in a strange, unexplained ripple effect."],
    ["Tantalus is unexpectedly promoted to a permanent advisory position on Mount Olympus, much to everyone's disbelief.", "Tantalus stays exactly in charge with nothing changing for him at all, continuing to run camp activities as before."],
    ["Dionysus is reinstated as camp's full-time leader instead, grumbling the whole time about having to actually show up now.", "Luke is somehow invited back to camp and quietly forgiven by the other campers, despite everything he's done."],
    ["Clarisse is instead punished for losing her original ship during the quest, assigned extra chores as a consequence.", "Percy ends up given all the credit instead of Clarisse, something that makes him uncomfortable given how the quest actually went."],
    ["Thalia's tree ends up destroyed completely in the process, undoing all the earlier rescue efforts and leaving everyone devastated.", "Thalia's spirit appears briefly as a translucent ghost near the tree but seems unable to fully return to life, fading in and out."],
  ],
  "pj-03-ch-01": [
    ["They went to rescue Annabeth, who had been kidnapped from the school earlier that week. Chiron had gotten a distress call from her captors and sent the three of them undercover to negotiate her release quietly.", "They went because Chiron ordered them to spy on a new camp for young monsters being built nearby. He worried the monsters were using Westover Hall as a cover to recruit human students into their ranks."],
    ["They are two satyrs training alongside Grover to search for new demigods, disguised as ordinary students so nobody at the school would suspect the truth. Grover had been mentoring them for months as part of their searcher training.", "They are teachers at Westover Hall who secretly work for Camp Half-Blood, keeping watch over the students in case a monster ever showed up. Chiron had placed them there years earlier just for this kind of emergency."],
    ["They forged transfer papers on Annabeth's laptop the night before, printing out fake records that listed them as new students from another boarding school. It was risky, but the paperwork was convincing enough to fool the front office staff.", "Chiron called ahead and enrolled them officially as exchange students, arranging everything through a mortal contact who worked in the admissions office. The plan let them walk in through the front door without anyone questioning their story."],
    ["Dr. Thorn kept insisting he had met Percy's mother somewhere before, bringing it up awkwardly every time he passed Percy in the hallway. It made Percy nervous, though he assumed it was just an odd coincidence.", "Dr. Thorn was secretly wearing a Camp Half-Blood necklace under his suit, which Percy noticed glinting whenever the man's collar shifted. Percy couldn't figure out how a stranger would have gotten hold of something like that."],
    ["Grover told them Pan had finally been found hiding in the school basement, and that they needed to hurry before the wild god slipped away again. It seemed almost too good to be true after Grover's years of fruitless searching.", "Grover told them Annabeth's father worked as a teacher at the school, and that finding him might explain some of Annabeth's memories from her childhood. He suggested they track the man down as their real reason for coming."],
  ],
  "pj-03-ch-02": [
    ["Dr. Thorn turns out to be a minor Titan in disguise, testing the young heroes to see if they were strong enough to be worth capturing for his master's army. He'd been posing as a teacher for months just waiting for the right moment to strike.", "Dr. Thorn turns out to be a cyclops working secretly for Luke, using a glamour spell to hide his single eye and monstrous size from the students. He'd been feeding information about demigods back to Luke's camp for weeks."],
    ["A squad of satyrs led by Grover's uncle bursts in to help, arriving just in time with makeshift weapons fashioned from tree branches and stones. They'd been tracking the manticore's scent through the woods for days.", "Chiron gallops in on his horse half to join the fight personally, having sensed danger from camp and racing the whole way without stopping. His arrival gives the exhausted teens a much-needed boost of confidence."],
    ["Annabeth is captured and locked inside the school by Dr. Thorn's assistants, who drag her off while the others are busy fighting the manticore itself. Her friends realize she's missing only after the chaos finally settles down.", "Annabeth chases the manticore into the woods and gets lost overnight, following its trail deep into unfamiliar terrain far from the school grounds. Her friends spend hours searching before giving up until morning."],
    ["The manticore breathes a cloud of poisonous gas to knock everyone out, forcing Percy and his friends to hold their breath and scatter across the courtyard. Anyone who inhales too much of the fumes collapses instantly.", "The manticore summons a pack of skeleton warriors to fight alongside it, calling them up from the ground with a chilling howl that echoes across the school grounds. Percy and his friends suddenly find themselves outnumbered on two fronts."],
    ["They feel triumphant because they captured Dr. Thorn and can question him, believing his capture means they've finally gotten ahead of the enemy's plans. Percy is eager to interrogate him the moment he wakes up.", "They feel relieved because Grover confirms he saw Annabeth escape safely, having watched her slip away from the fight moments before the manticore leaped off the cliff. It takes a weight off Percy's shoulders to hear the good news."],
  ],
  "pj-03-ch-03": [
    ["Percy's father Poseidon rises out of a nearby lake to explain everything, telling the group that the sea itself had sensed Annabeth's fall and could track where she went. He promises to keep searching the currents for any sign of her.", "Dr. Thorn's twin brother arrives to confess what really happened, admitting that the two of them had planned the ambush together for weeks. He offers to help the group find Annabeth in exchange for being spared."],
    ["Bianca has to decide whether to return to Westover Hall or move to Camp Half-Blood, weighing whether school life or a demigod's life would be safer for her and Nico. Either way, she knows the choice will change both of their futures.", "Bianca has to decide whether to tell Nico that their father is a Greek god, worried that the truth might be too much for her younger brother to handle right now. She isn't sure if keeping the secret longer would protect him or hurt him more."],
    ["Bianca decides to stay with Nico and refuses to join the Hunters, telling Zoe that she can't leave her little brother alone in such a dangerous world. Zoe accepts her answer, though she seems disappointed by the choice.", "Bianca decides to go home to her family instead of joining any group, saying she needs time to think things over away from all the fighting. Nico is relieved, but Percy worries that leaving might not really be safe for her."],
    ["Nico is thrilled and immediately asks to join the Hunters too, hoping he and Bianca could stay together even if it meant living by their strict rules. Zoe has to gently explain that boys are never allowed to become Hunters.", "Nico runs away from the group in anger and disappears into the woods, leaving everyone scrambling to search the dark trees for him. It takes Grover almost an hour to track him down and calm him back down."],
    ["Percy feels confident that everything is under control and no longer worries about Annabeth, trusting that the Hunters will locate her quickly with their tracking skills. He turns his attention instead to helping Bianca settle into her new life.", "Percy feels angry at Bianca for choosing to join the Hunters over her brother, thinking she should have put Nico's feelings ahead of her own future. He struggles to hide his frustration when he's around her."],
  ],
  "pj-03-ch-04": [
    ["Chiron sends a flying chariot pulled by pegasi to pick them up, guiding it personally from camp once he learns the quest went wrong at the school. The pegasi make quick work of the distance back toward New York.", "They call Percy's mom, who drives for hours to come get them, leaving work early the moment she hears the kids are stranded far from camp. It's an exhausting, ordinary car ride compared to their usual demigod adventures."],
    ["Thalia doesn't have her license yet, so she isn't legally allowed to drive, though she insists on taking the wheel anyway since nobody else wants to argue with her. Her lack of paperwork ends up being the least of their worries.", "Thalia is afraid of water and refuses to drive near the coast, forcing the group to take a much longer route further inland than they'd planned. Her fear makes her tense and short-tempered the whole way."],
    ["She accidentally drives them into the ocean and they have to swim to shore, having lost control of the chariot right as it swooped in low over the water. Everyone ends up soaked and shaken after climbing out onto the beach.", "She gets them lost for days trying to find the right highway, circling the same unfamiliar towns again and again as her frustration builds. The delay costs them valuable time they didn't have to spare."],
    ["They run out of fuel in the middle of a forest, far from camp, forcing them to hike the rest of the way on foot through the dark. It takes them until dawn to finally reach the safety of the borders.", "Police officers pull them over and end the ride early, forcing the group to abandon the vehicle and continue on foot to avoid awkward questions. They arrive at camp late and completely worn out from walking."],
    ["Thalia feels bored and unimpressed by the whole trip, complaining that she'd rather be walking than riding in such an unreliable, old-fashioned vehicle. Her constant complaints annoy everyone else in the group.", "Thalia feels excited and asks to drive again right away, laughing off the chaos as the most fun she's had in weeks. Percy is stunned that she wants another turn after everything that just happened."],
  ],
  "pj-03-ch-05": [
    ["Percy uses a special phone Chiron gives him to text the gods directly, typing out a quick message and hoping it somehow reaches the right god through Olympian magic. It feels strange texting for help instead of using the usual rainbow message.", "Percy borrows Apollo's chariot to fly down to the ocean floor, figuring the sun god's ride could get him underwater faster than swimming ever could. The chariot sputters and struggles the moment it touches the waves."],
    ["Percy speaks directly with Zeus about the missing goddess Artemis, surprised that the king of the gods would bother taking his call at all. Zeus is gruff but gives him a few grudging details about the search.", "Percy talks with Dr. Thorn, who tries to trick him with false information, pretending to be a friendly messenger sent by Poseidon to check in on him. Percy almost falls for it before noticing something off about the voice."],
    ["He learns that Poseidon has decided to leave Olympus completely, tired of the constant squabbling among the other gods over their duties. The news leaves Percy stunned and unsure what it means for his own future.", "He learns that the ocean's monsters have joined forces with Artemis, banding together to help her hunt down whoever is responsible for her disappearance. It's surprising news that doesn't quite add up to Percy."],
    ["He hears that Bianca has changed her mind and left the Hunters already, deciding barely a day after joining that the lifestyle wasn't right for her. Percy isn't sure how he feels about the sudden reversal.", "He hears that Dr. Thorn has been captured and imprisoned by the gods, locked away somewhere deep beneath the ocean where he can't cause any more trouble. It's satisfying news, but it doesn't answer what happened to Annabeth."],
    ["Percy feels completely calm, believing all of his problems are now solved after hearing from his family beneath the waves. He heads back to the surface with a lighthearted sense that everything will work out fine.", "Percy feels ready to give up the search for Annabeth entirely, convinced by the call that there's nothing more he can do to help her. It takes his friends a long talk to snap him out of that mindset."],
  ],
  "pj-03-ch-06": [
    ["Percy finds a letter Annabeth wrote saying she planned to run away from camp, hidden inside a book she'd left behind in her cabin. Reading it makes Percy question everything he thought he knew about her.", "Percy finds Annabeth's dagger buried near the cabins, half-covered in dirt as though someone had tried to hide it there deliberately. Seeing her weapon abandoned like that fills him with dread."],
    ["Dr. Thorn crashes the game, still disguised as a teacher, storming onto the field and demanding to know where Percy and his friends have been hiding. Everyone scatters in a panic before Chiron manages to intervene.", "Grover shows up riding the Erymanthian Boar in the middle of the field, startling every camper as the massive creature comes crashing through the trees. Nobody expects to see Grover show up on the back of a giant pig."],
    ["The Oracle delivers a letter from Poseidon addressed to Percy, sealed with a wax trident stamp and written in careful, formal handwriting. Percy is too stunned to open it in front of everyone.", "The Oracle delivers a warning that Camp Half-Blood is about to be destroyed, speaking in a hoarse voice that sends chills through the crowd of campers. Everyone immediately starts asking Chiron what they should do next."],
    ["They laugh it off, assuming someone is playing a prank in a costume, since the Oracle hasn't left its attic in longer than anyone can remember. It takes several minutes before anyone realizes it's actually real.", "They cheer, thinking it means the quest is already finished successfully, celebrating what they assume must be good news about Annabeth. Chiron has to quiet everyone down once he realizes what's actually happening."],
    ["Because Percy officially becomes the camp's new activities director, a title Chiron gives him as a reward for handling the Westover Hall mission so well. It's an honor, but it doesn't feel like much comfort with Annabeth still missing.", "Because Percy learns for certain that Annabeth has already been found safe, receiving the news just as the Oracle's prophecy is delivered to the crowd. It's a huge relief that makes the rest of the chapter feel almost cheerful."],
  ],
  "pj-03-ch-07": [
    ["Because Chiron bans him from camp activities for a week, punishing him for sneaking off to Westover Hall without official permission from the counselors. Percy feels humiliated having to sit out while everyone else trains.", "Because the other campers vote him out of his cabin, deciding in a surprise meeting that he should room somewhere else for the rest of the summer. Percy has no idea what he did to deserve such a strange punishment."],
    ["Percy dreams that Bianca has secretly betrayed the Hunters, passing information about their location back to Luke in exchange for some kind of promise. The dream leaves Percy questioning whether he can really trust her.", "Percy dreams that his mother has gone missing along with Annabeth, both of them locked away somewhere he can't quite make out in the shifting dream images. He wakes up in a cold sweat, terrified for both of them."],
    ["Tyson shows up in person to help Percy sneak onto the quest, having snuck away from his underwater work to come find his brother at camp. Percy is thrilled but worried Tyson might get in trouble for leaving.", "Dr. Thorn's shadow appears at the edge of camp, spying on Percy, though the camp's magical borders keep it from actually getting inside. Percy reports the sighting to Chiron right away, unsettled by how close it came."],
    ["He feels relieved, since he was hoping for a break from questing, admitting to himself that facing another dangerous journey right now sounds exhausting. Part of him is almost grateful to just watch from the sidelines.", "He feels proud that Zoe finally trusts him completely, assuming her decision not to pick him means she believes he can handle things on his own instead. It takes him a while to realize that's not actually what happened."],
    ["The General is revealed in the dream to be Dr. Thorn's older brother, another manticore working alongside Luke to build up Kronos's forces. Percy recognizes the family resemblance immediately in the dream.", "The General is shown clearly to be the Titan lord Kronos himself, appearing in Percy's dream in his full terrifying golden form. Percy wakes up shaking, certain now exactly who they're truly up against."],
  ],
  "pj-03-ch-08": [
    ["They fly off together to spy on Dr. Thorn's hideout, sneaking close enough to overhear his plans without being spotted from above. It's a tense flight that leaves Percy with more questions than answers.", "They race across camp to warn Chiron about an attack, rushing to deliver the news before the enemy forces can get any closer to the borders. Blackjack flies as fast as he can while Percy holds on tight."],
    ["Nico asks Percy to promise never to tell anyone about their father, worried that other campers might treat him differently once they learn who his godly parent is. Percy agrees, though he isn't sure how long he can keep such a big secret.", "Nico asks Percy to promise to bring him along on the quest too, insisting he's old enough to help protect his sister himself. Percy has to gently explain why that's just too dangerous for Nico right now."],
    ["He disguises himself as one of the Hunters to sneak onto the team, borrowing a silver jacket and keeping his head down so nobody notices he doesn't belong. It works for a while before someone finally spots him.", "He convinces Chiron to order Zoe to add him to the group, using his connections at camp to pull rank on the Hunters' leader. Zoe reluctantly agrees, though she makes it clear she isn't happy about it."],
    ["Bessie is a baby sea dragon that belongs to Poseidon's palace, accidentally wandered off from the underwater kingdom and gotten lost near the surface. Percy recognizes it right away as one of his father's prized creatures.", "Bessie is a disguised Hunter who got turned into an animal by a curse, trapped in that form until someone can figure out how to reverse the spell. Percy feels sorry for the poor creature the moment he sees it."],
    ["Because keeping the promise means Percy has to break a sacred camp rule, one that strictly forbids any camper from revealing details about another demigod's unclaimed parent. Breaking it could get him in serious trouble with Chiron.", "Because the promise requires Percy to give up his own godly parent's protection, trading away Poseidon's favor in exchange for keeping Bianca safe during the quest. It's a steep price that worries Percy more than he lets on."],
  ],
  "pj-03-ch-09": [
    ["He hides inside one of the Hunters' supply crates on their van, curling up uncomfortably among the gear and hoping nobody opens the lid too soon. It's a cramped and nerve-wracking way to travel.", "He disguises his voice using a magic item borrowed from Annabeth, mimicking one of the Hunters so he can blend in during their radio check-ins. It's a clever trick, but keeping it up the whole trip proves exhausting."],
    ["He watches Luke building a fake Camp Half-Blood to trick new demigods, constructing an entire replica camp meant to lure unsuspecting kids straight into Kronos's army. It's a chilling plan that Percy can hardly believe.", "He watches the General freeing Kronos from the underworld, chanting over a glowing pit that seems to pull the Titan lord's essence up from somewhere far below. The sight fills Percy with dread about what's coming."],
    ["He convinces the skeleton warriors that he's on their side, bluffing his way past them with a confident lie about being sent by the General himself. It's a risky gamble that somehow actually works.", "He transforms into water and slips away through a drainpipe, using a trick he picked up from his father to squeeze through the narrow opening unseen. It leaves him soaked but safely out of sight."],
    ["Percy grabs one of the dragon's teeth as proof of what he saw, tucking the sharp, unsettling fang into his pocket to show the others later. It feels like solid evidence of the horrifying army being grown.", "Percy grabs a map showing the location of Mount Olympus, snatching it off a table while the General and Luke are distracted with their ritual. He hopes it might come in useful somehow later on."],
    ["He decides to keep what he saw a secret from everyone, including Thalia, worried that telling anyone might put him in trouble for sneaking along on the quest. He plans to figure out what to do about it on his own.", "He goes straight back to camp instead of warning the quest group, deciding the news is too big to explain and that Chiron needs to hear it first. It takes precious time away from the friends who need the warning most."],
  ],
  "pj-03-ch-10": [
    ["Percy finds them hiding inside a cave near Camp Half-Blood, having tracked their scent for miles before finally spotting the entrance where they'd taken shelter. It's a relieved reunion after such a long search.", "Percy finds them already fighting Dr. Thorn on a rooftop, arriving just in time to see Zoe and Thalia dodging his poisonous spikes above the city streets. He rushes up to help before things get any worse."],
    ["A giant scorpion made of bronze attacks from inside a display case, bursting free of the glass the moment the group gets too close to it. Its metal claws prove just as tough as any monster's natural hide.", "A pack of skeleton warriors ambushes them right in the museum halls, swarming out from behind exhibits with swords raised before anyone can react. The group barely has time to draw their own weapons."],
    ["They trap the lion inside a rocket ship display and launch it away, sealing the hatch just before triggering the display's fake launch sequence. It's a wild, improvised plan that somehow gets rid of the beast.", "They discover a hidden weak spot behind the lion's ear, a soft patch of skin Annabeth had read about once in an old bestiary. Zoe aims carefully and manages to strike it before the lion can react."],
    ["Zoe gives Percy her personal silver hunting bow as a reward, telling him it's the highest honor she can offer someone outside the Hunters. Percy is stunned by the unexpected gesture of trust.", "Zoe gives Percy a map showing exactly where Annabeth is being held, information she says she picked up from a contact back at camp. It's the first real clue they've had about where to search."],
    ["Percy is named the new leader of the quest, replacing Zoe, after the others agree his quick thinking with the lion proved he deserved the role. Zoe steps back, though she still keeps a close eye on him.", "Percy is sent back to camp as punishment for following the group, ordered by Zoe to return immediately despite his help defeating the lion. He argues but ultimately has no choice but to agree."],
  ],
  "pj-03-ch-11": [
    ["A giant eagle sent by Zeus tracks their every move, circling high above the train and occasionally swooping low enough to make everyone nervous. Nobody is sure whether it means to help them or report on them.", "Dr. Thorn himself pilots a small plane right above them, buzzing low over the train tracks in an attempt to spot exactly where they're hiding. The group has to duck out of sight whenever it passes overhead."],
    ["They borrow Professor Chase's private plane to fly west, a generous offer that lets them cover huge distances in a fraction of the time. It's a smooth, comfortable ride compared to their usual travels.", "They ride on the back of the Erymanthian Boar the whole way, holding on tight as the enormous creature thunders across the plains toward California. It's an exhausting, bumpy way to make such a long journey."],
    ["They meet Hades disguised as a train conductor, punching tickets in a dusty, cold uniform while quietly studying the demigods with unreadable eyes. His presence makes everyone nervous, though he says nothing threatening.", "They meet Annabeth's father, who happens to be riding the same train, surprised and thrilled to run into Percy and the others so far from home. He offers what little help and encouragement he can before their stop."],
    ["He tells them Annabeth is being held at the bottom of a lake, somewhere hidden deep beneath the water where the Mist keeps mortals from ever noticing. It gives them a location to aim for, at least.", "He tells them Bianca secretly still wants to leave the Hunters, confiding that he overheard her expressing doubts about her choice not long before she disappeared. It leaves Percy with conflicting feelings about her decision."],
    ["They feel completely safe, certain nothing can catch up to a moving train, settling into a relaxed rhythm for the first time since the quest began. It's a rare moment where nobody seems worried at all.", "They feel ready to give up the quest and head back to camp early, exhausted and discouraged by how little progress they seem to be making. It takes a pep talk from Zoe to keep everyone moving forward."],
  ],
  "pj-03-ch-12": [
    ["An avalanche nearly buries the whole group in snow, tumbling down the mountainside without warning just as they're crossing a narrow ridge. They barely scramble to safety before the wall of snow crashes past them.", "Dr. Thorn ambushes them disguised as a ski instructor, catching the group off guard on the slopes before revealing his true monstrous form. They have to fight him off in the middle of the snowy chaos."],
    ["A massive griffin swoops down to help fight the skeletons, diving out of the clouds with talons extended to tear through their bony ranks. Its sudden arrival turns the tide of the fight in their favor.", "The Nemean Lion returns for a rematch against Zoe, somehow surviving its earlier defeat and tracking them all the way into the mountains. Zoe groans, wishing they'd finished the job the first time."],
    ["Grover tames the boar by feeding it enchanted acorns from camp, coaxing it closer bit by bit until it finally lets him climb onto its back. It takes patience, but eventually the massive creature calms down completely.", "Grover uses a rope lasso to force the boar to carry them, roping its enormous tusks and hanging on for dear life as it thrashes to break free. It's a rough, dangerous way to get the animal moving in the right direction."],
    ["Grover realizes the boar was actually sent by Dr. Thorn as a trap, meant to lure them somewhere even more dangerous once they let their guard down. It makes him suspicious of accepting its help at all.", "Grover realizes the boar escaped from a nearby traveling circus, recognizing a faded tattoo on its hide from a show he once saw as a kid. It explains the boar's odd, almost tame behavior around people."],
    ["It's a calm, quiet ride since the boar moves slowly and carefully, giving everyone a chance to rest and catch their breath after the fight in the mountains. Nobody expected the journey to feel so peaceful.", "It's a sad moment because the boar gets hurt and can't continue, forcing the group to leave it behind and finish the desert crossing on foot. Grover is heartbroken at having to abandon the injured creature."],
  ],
  "pj-03-ch-13": [
    ["The boar brings them straight to the gates of Mount Olympus, dropping them off right at the base of the mountain where the gods' city rises into the clouds. It's a stunning sight none of them expected to see so soon.", "The boar brings them to a hidden Hunters of Artemis campsite, tucked away in a canyon where silver tents and watchful wolves guard the perimeter. It's a welcome surprise after such a long, exhausting ride."],
    ["Bianca takes a golden apple meant for the Hunters' garden, slipping it into her pocket without realizing it was never meant to leave the junkyard. The theft ends up drawing unwanted attention almost immediately.", "Bianca takes a silver arrow that once belonged to Zoe, hoping to have it repaired somewhere as a thoughtful gift for her friend. Picking it up sets off an alarm she never saw coming."],
    ["A sleeping Titan buried under the scrap metal wakes up, stirring slowly beneath tons of rusted parts before bursting free in a shower of debris. Its sheer size dwarfs everything else in the junkyard.", "An army of skeleton warriors bursts out from beneath the junk piles, clawing their way up through the rusted metal with swords already drawn. The group is instantly surrounded on every side."],
    ["Bianca climbs onto Talos's shoulder and tries to pull out its wiring, clinging to the giant automaton's frame as it lurches wildly beneath her. It's a desperate, exposed position to be fighting from.", "Bianca lures Talos toward the boar so it gets crushed instead, running just ahead of its massive footsteps to guide it toward their exhausted animal companion. It's a heartbreaking plan that costs them their loyal ride."],
    ["Bianca is captured by Talos and carried away, still alive but missing, clutched inside its massive metal fist as it stomps off into the desert. Her friends chase after it uselessly as it disappears from sight.", "Bianca manages to escape at the last second, badly hurt but safe, tumbling out of the hatch moments before Talos crashes into the power lines. Her friends rush to her side, relieved she made it out alive."],
  ],
  "pj-03-ch-14": [
    ["They hitch a ride on a passing freight train once again, climbing aboard a boxcar just like they did earlier in their journey west. The rattling ride gives them time to grieve quietly over what happened to Bianca.", "They fly the rest of the way using Blackjack and other pegasi, who arrive just in time to carry the grieving group toward the Hoover Dam. It's a fast but somber journey through the clouds."],
    ["They meet a mortal tour guide who turns out to be Apollo again, cracking jokes and offering cryptic hints while leading them through the dam's exhibits. His disguise fools everyone until he starts speaking in rhyming verse.", "They meet another demigod who has been secretly living at the dam, hiding out there for years after running away from a camp back east. She offers to help them avoid the tourists swarming the visitor center."],
    ["Dr. Thorn ambushes them disguised as a cafeteria worker, revealing his true form the moment he corners them near the food court's kitchen. The group has to scramble for an escape route through the crowded tourists.", "The Nemean Lion's ghost appears and traps them inside, its spectral form blocking every exit while it prowls hungrily around the food court. It's a terrifying, unexpected reappearance of an old enemy."],
    ["Rachel Elizabeth Dare distracts the guards so they can slip away, cleverly pretending to faint near the entrance so security rushes to help her instead. It buys the group just enough time to sneak out unnoticed.", "Grover charms the skeleton warriors into falling asleep with his pipes, playing a slow, hypnotic tune that makes the bony soldiers collapse right where they stand. It's a strange and welcome use of his satyr magic."],
    ["Zoe reveals that Percy's sword was actually a gift from Luke, passed down to Percy without anyone realizing where the blade had originally come from. It's an unsettling connection nobody had considered before.", "Zoe reveals that the sword once belonged to Dr. Thorn before he became a monster, back when he was still a mortal hero fighting on the side of good. It's a strange piece of history tied to their current enemy."],
  ],
  "pj-03-ch-15": [
    ["The statues drop them off right at the base of Mount Tamalpais, setting them down gently among the trees before turning back to stone once again. It's a shorter final leg to the mountain than they expected.", "The statues drop them off at Professor Chase's front door, delivering them straight to Annabeth's father's house without any explanation of how they knew the address. He's startled but welcomes them inside immediately."],
    ["Percy has to wrestle Luke to get information about Annabeth, grappling with his old friend turned enemy right there on the crowded wharf. Neither of them manages to land a clean hit before Luke slips away.", "Percy has to wrestle a giant sea serpent guarding the harbor, wrapping his arms around its slick, thrashing body while trying to avoid its snapping jaws. It's an exhausting struggle that takes everything he has."],
    ["Nereus reveals that Annabeth is being kept prisoner nearby in San Francisco, locked away in a building not far from where they're standing at that very moment. It gives them fresh hope that she's close by.", "Nereus reveals that Zoe secretly wants to quit the Hunters, confiding that she's confessed doubts about her centuries-long commitment to Artemis. It's surprising information that Percy isn't sure what to do with."],
    ["Luke shows up alone, offering to switch sides and help them, claiming he's grown tired of serving Kronos and wants to make amends. Percy doesn't know whether to trust him or brace for a trick.", "The Nemean Lion's mate arrives seeking revenge, prowling out from the wharf's shadows with the same impossibly tough hide as before. The group groans at having to face another version of the same monster."],
    ["Percy tricks Nereus by offering him a trade of golden treasure, promising a chest of Olympian riches in exchange for one honest answer. Nereus considers it greedily before finally agreeing to the deal.", "Percy convinces Nereus using a message sent from Poseidon, presenting a sealed scroll from his father that orders the old sea god to cooperate. Nereus grumbles but obeys the request from his fellow god."],
  ],
  "pj-03-ch-16": [
    ["Grover decides to stay behind and guard Professor Chase's house, worried that Dr. Thorn's mercenaries might track the group back there while they're gone. He sets up watch outside while the others continue on.", "Grover heads off to search for Pan on his own instead, following a fresh lead he picked up from a nearby dryad about the wild god's location. He promises to catch back up with the group soon."],
    ["They visit Luke's father, hoping he can talk his son out of fighting them, tracking down a man who hasn't seen or spoken to Luke in years. He's shocked to hear what his son has become.", "They visit Dr. Thorn's old teaching colleague for information, hoping the man might know something useful about where the manticore has been hiding. He's reluctant to talk at first but eventually shares a few clues."],
    ["A giant scorpion the size of a house guards the garden entrance, its pincers large enough to snap a demigod in half with one bite. Getting past it seems nearly impossible without a serious distraction.", "A pack of skeleton warriors stands watch at the garden gates, swords drawn and eyes glowing faintly as they patrol back and forth. The group has to find another way in without alerting them."],
    ["Zoe reveals that the General is secretly her long-lost brother, someone she believed had died centuries ago fighting on the wrong side of an old Titan war. Learning he's alive shakes her more than she lets on.", "Zoe reveals that the General is actually Luke's father in disguise, a mortal man who somehow gained monstrous power after making a deal with Kronos. It's a painful truth Luke never wanted anyone to know."],
    ["Zoe uses a magic flute to lull the dragon to sleep, playing a haunting tune passed down among the Hunters for exactly this kind of situation. It works just long enough for Percy and Thalia to slip by.", "Zoe offers the dragon a golden apple as a bribe to let them pass, tossing it a fruit from the garden itself in hopes it would rather eat than fight. Ladon snaps it up but still doesn't budge from its post."],
  ],
  "pj-03-ch-17": [
    ["They find Artemis chained up inside a cave, unable to move at all, bound tightly by thick iron shackles that glow faintly with Titan magic. Seeing the goddess so helpless shocks everyone in the group.", "They find Artemis has already escaped and left the mountain, with only a hastily scrawled note explaining that she'd freed herself and gone ahead to warn Olympus. The group is left confused about what to do next."],
    ["Chiron is found captive there, having been kidnapped days earlier, bound and weakened after being lured away from camp under false pretenses. Seeing their old mentor in chains stuns Percy and the others.", "Nico is discovered there, having secretly followed the group, hiding among the rocks after sneaking away from camp without anyone noticing. Percy is furious and terrified that Nico put himself in such danger."],
    ["Luke tries to convince Thalia to free Atlas from his Titan prison, arguing that releasing him would finally tip the balance of power in their favor. Thalia refuses, disgusted that Luke would even suggest it.", "Luke tries to convince Thalia to abandon Percy on the mountain, claiming that leaving him behind would somehow spare her from an even worse fate later. Thalia angrily rejects the idea outright."],
    ["Percy tricks Atlas into a wrestling match to distract him completely, challenging the Titan's pride until he sets down the sky just long enough to accept. It's a clever ploy that catches Atlas off guard.", "Percy uses Riptide to cut through the chains holding Artemis in place, slicing carefully through the Titan-forged metal binding her wrists and ankles. It takes several precise strikes to finally free her."],
    ["Artemis defeats Atlas by calling down lightning from her father, Zeus, striking the Titan again and again until he's too weakened to keep fighting. The bolts crackle across the mountaintop in a dazzling display.", "Artemis defeats Atlas by trapping him inside the dragon Ladon's lair, luring him down the mountain and sealing the entrance shut behind him. It's a clever trick that keeps him contained, at least for now."],
  ],
  "pj-03-ch-18": [
    ["Zoe refuses all healing because she believes it's against the Hunters' code, insisting that facing her fate without magical help is the only honorable way to go. Her stubbornness leaves her friends heartbroken and helpless.", "Zoe hides her injuries at first, so nobody realizes how badly hurt she is, insisting she's fine even as her strength quietly fades throughout the fight. By the time anyone notices, it's already too late to help her."],
    ["Thalia and Zoe argue one final time about who is to blame for the battle, each insisting the other made the fatal mistake that cost them so much. It's a painful, bitter exchange neither of them can take back.", "Zoe asks Thalia to take her place as leader of the Titans instead, a strange and confusing request that leaves everyone around them baffled. Thalia has no idea how to respond to something so unexpected."],
    ["Zoe confesses that she always secretly worked for Atlas, feeding him information about the Hunters' movements in exchange for keeping Nico and Bianca safe. It's a shocking betrayal that Percy struggles to process.", "Zoe confesses that she knew all along that Bianca wouldn't survive, having seen a vision of her death long before the quest ever began. She admits she said nothing, hoping to be wrong."],
    ["Artemis brings Zoe back to life using a hidden immortality potion, an ancient elixir she's kept in reserve for only the most desperate circumstances. Zoe wakes weak but very much alive.", "Artemis names a new Hunter cabin at camp after Zoe, ordering that a permanent shrine be built there in her memory for future Hunters to visit. It becomes a quiet, respected part of camp life."],
    ["They feel triumphant and mostly forget about Zoe quickly, eager to celebrate rescuing Artemis and Annabeth without dwelling much on what was lost. It surprises Percy how fast everyone moves on.", "They feel angry at Artemis for not saving Zoe sooner, blaming the goddess for taking too long to intervene once the fighting had already started. It creates a tense, uncomfortable mood among the group."],
  ],
  "pj-03-ch-19": [
    ["They suggest banning Percy from ever visiting Camp Half-Blood again, arguing that keeping him away entirely would be the safest way to avoid the prophecy altogether. It's a harsh suggestion that leaves Percy stunned.", "They suggest taking away Percy's ability to control water, claiming that stripping him of his powers would make him far less dangerous down the road. Poseidon bristles at the idea the moment it's raised."],
    ["The gods punish Percy by turning him into a minor forest spirit for a year, a strange and humiliating sentence meant to keep him powerless until they decide what to do next. Percy can hardly believe what he's hearing.", "The gods decide to erase Percy's memory of the entire quest, ruling it the safest way to keep him from ever becoming the demigod named in the prophecy. Chiron argues against it, but the vote still leans that way for a while."],
    ["The gods decide the Ophiotaurus must be sacrificed immediately for safety, arguing that letting such a dangerous creature survive is too great a risk to Olympus. Poseidon protests, but he's outvoted.", "The gods decide to release the Ophiotaurus back into the wild ocean, figuring it would be safest simply left alone somewhere far from any demigod's reach. It's a quieter resolution than anyone expected."],
    ["Thalia decides to become a full Olympian goddess herself, accepting an offer from Zeus that would place her permanently among the ruling gods. It's a stunning honor that changes everything about her future.", "Thalia decides to leave the group entirely and live as a mortal, wanting nothing more to do with quests, prophecies, or godly business. Percy is surprised by how sudden the decision feels."],
    ["It means the prophecy is now completely canceled and will never happen, since Thalia's choice apparently satisfied whatever condition the prophecy required. Everyone breathes a sigh of relief at the news.", "It means Nico instead becomes the one the prophecy is definitely about, since his recently discovered parentage suddenly makes him a more likely candidate. Percy feels an unexpected wave of relief at the shift."],
  ],
  "pj-03-ch-20": [
    ["Percy has to tell Nico that Bianca decided to stay with the Hunters forever, breaking the news that she chose their sisterhood over ever coming back to see him. It's a painful conversation, though not nearly as devastating as the truth.", "Percy has to tell Nico that their father wants nothing to do with him, delivering a rejection that feels almost as crushing as losing a sibling entirely. Nico's face falls the instant he hears it."],
    ["Nico calmly accepts the news and thanks Percy for trying his best, surprising everyone with how composed he manages to stay despite the tragedy. His quiet reaction unsettles Percy more than an outburst would have.", "Nico refuses to believe it and runs off to search for Bianca himself, convinced that Percy must be mistaken or lying about what really happened. It takes the whole group hours to track him down."],
    ["Nico summons a wave of water strong enough to wash the warriors away, an ability nobody expected from him since water powers belong to Poseidon's children. Percy is baffled watching it happen.", "Nico calls down a bolt of lightning to destroy the warriors instantly, a display of power that looks eerily similar to what Thalia, daughter of Zeus, can do. Everyone stares in stunned silence."],
    ["Percy figures out that Nico is secretly one of the Hunters in disguise, sent along on the quest from the very beginning to keep an eye on the group. It explains a few strange things Percy noticed earlier.", "Percy figures out that Nico has been working with Luke all along, secretly passing along information in hopes of bringing his sister back to life. Percy struggles with what to do with such a troubling discovery."],
    ["Grover announces that he's found a whole new herd of satyrs to join camp, having tracked down a group living wild in the forests who are eager to help search for Pan. It's exciting news that boosts morale.", "Grover announces that Dr. Thorn has been spotted again nearby, warning everyone that the manticore somehow survived his fall and is already plotting revenge. The news casts a shadow over an otherwise hopeful ending."],
  ],
  "pj-04-ch-01": [
    ["Percy bumps into Rachel outside a comic book store near his apartment, where he's stopped to buy a graphic novel before the school year starts.", "Percy spots Rachel at a summer art fair in Manhattan, standing beside a booth selling her own charcoal sketches of gargoyles."],
    ["Rachel explains that she's spent years secretly training in kickboxing, which is why she moves so fast during the fight.", "Rachel admits she's actually a descendant of a Greek hero on her mother's side, which is why monsters seem drawn to her."],
    ["The two cheerleaders, Tammi and Kelli, turn out to be Furies in disguise, sent by Hades to drag Percy down to the Underworld.", "The two cheerleaders, Tammi and Kelli, are revealed as scouts working directly for Ares, testing Percy's fighting skills before a real battle."],
    ["Percy manages to wound both monsters badly with Riptide, but they retreat together into the school gym before he can finish them off.", "Percy loses his sword in the scuffle and has to rely on Rachel's umbrella to fend off Kelli until a teacher interrupts the fight."],
    ["Kelli tells Percy that Luke has already reached camp's borders and that Chiron has been taken prisoner, then she vanishes into smoke.", "Kelli warns him that Grover has betrayed the camp and joined Kronos's side, then she dissolves into a cloud of sulfurous dust."],
  ],
  "pj-04-ch-02": [
    ["Percy meets Ethan Nakamura, a new camper assigned to guard the sword arena, along with a small three-headed puppy he's secretly raising.", "Percy meets Chiron's cousin, a retired centaur named Argos, who brought along a chariot pulled by fire-breathing horses."],
    ["The Council tells Grover that his search license has already been revoked and there's nothing left to appeal.", "The Council tells Grover that Pan has been officially declared dead by vote, so further searching is now pointless."],
    ["Percy reunites with his mother, Sally, who has come to camp for a surprise visit with Paul.", "Percy reunites with Clarisse, who has just returned from a solo scouting mission near the beach."],
    ["Percy gets a flickering vision of Luke standing over Kronos's golden coffin in a dim cabin, murmuring plans to time an attack on camp with the summer solstice, when its defenses are weakest.", "Percy gets a flickering vision of Annabeth trapped somewhere dark and cold, calling out his name over and over and begging someone, anyone, to come find her before it's too late."],
    ["The ghost mentions that only a child of the Big Three could complete the trade, which makes Percy think of Nico himself instead.", "The ghost explains that the trade requires someone who has already died once before, which makes Percy suspect it might be about Bianca returning as a spirit only."],
  ],
  "pj-04-ch-03": [
    ["A squad of Laistrygonian giants storms the beach, and Clarisse's cabin has to hold the line until reinforcements arrive.", "A swarm of stymphalian birds descends on the strawberry fields, and the Demeter cabin scrambles to scare them off with pruning shears."],
    ["She reveals that she and Chris Rodriguez have been secretly mapping the ocean floor for a hidden route to Poseidon's palace.", "She reveals that she and Grover have been searching the woods every night for a sign of where Pan might be hiding."],
    ["She thinks Luke's side wants the Golden Fleece, believing it could heal Kronos's shattered body faster than anything else.", "She thinks Luke's side wants a stash of ambrosia hidden somewhere in the maze to keep their forces alive during the invasion."],
    ["Three giant scorpions chase them all the way to the lake, where Percy has to use his water powers to wash the creatures away.", "Three giant scorpions trap them against Thalia's pine tree until Grover arrives with his reed pipes to charm the creatures still."],
    ["They find a stone stairway carved with images of the Minotaur, leading down toward what looks like an old training arena.", "They find a rusted iron gate covered in vines, marked with a symbol that Annabeth identifies as belonging to the god Hephaestus."],
  ],
  "pj-04-ch-04": [
    ["Percy dreams of modern-day Manhattan, where Luke stands atop a skyscraper directing an army of monsters toward the Empire State Building.", "Percy dreams of the ocean floor, where Poseidon argues with Oceanus about who truly commands the sea's ancient currents."],
    ["Chiron suggests that the Labyrinth itself has become sentient and is now working directly for Kronos.", "Chiron suggests that Quintus already knows the way to Daedalus and should be trusted to lead the quest himself."],
    ["Annabeth proposes a quest to find Pan alongside Grover, and the Oracle instead gives her a warning about betrayal within camp's own walls.", "Annabeth proposes a quest to rescue Nico from Minos's ghost, and the Oracle's prophecy names Quintus as the true villain."],
    ["Camp tradition allows a quest leader only two companions, but Annabeth insists on going completely alone instead, against Chiron's direct orders.", "Camp tradition allows a quest leader only two companions, but Annabeth secretly swaps out Grover for Clarisse at the very last minute."],
    ["Juniper mentions she overheard Quintus muttering in ancient Greek near Zeus's Fist, though she couldn't make out what he was saying.", "Juniper mentions she saw Quintus feeding Mrs. O'Leary scraps of meat that smelled strongly of sulfur, which struck her as odd."],
  ],
  "pj-04-ch-05": [
    ["Percy dreams of Ethan Nakamura swearing loyalty to Kronos aboard the Princess Andromeda, promising to lead Luke's forces through camp's back entrance.", "Percy dreams of Annabeth arguing with Luke on a rooftop, insisting he still has a chance to abandon Kronos before it's too late."],
    ["It shows a live vision of Grover wandering a foggy forest, calling out for Pan while playing a mournful tune on his pipes.", "It shows a live vision of Rachel sketching furiously in her bedroom, drawing images of a maze that seem to move on the page."],
    ["Nico summons the ghost of Daedalus himself, who refuses to speak and simply vanishes back into the shadows.", "Nico summons the ghost of King Minos, who immediately begins bragging about how the Labyrinth still obeys him."],
    ["Theseus warns Nico that Kronos already commands enough raw power to rise again on his own, without needing any soul trade at all, and that the ritual would accomplish nothing but grief.", "Theseus warns Nico that Percy is fated to betray everyone he loves in the end, and insists that trusting anyone else while wandering through the Labyrinth is nothing but a fatal mistake."],
    ["The fountain water turns to blood and Nico's voice cries out for help, so Percy dives through the portal to try to save him.", "The fountain flickers and shows Luke's face laughing directly at Percy, so Percy throws a shoe at it to break the connection."],
  ],
  "pj-04-ch-06": [
    ["They stumble into a marble courtyard lined with statues of past Labyrinth explorers, each one frozen mid-scream.", "They wander into an abandoned subway platform covered in old advertisements, with a single flickering lightbulb overhead."],
    ["They find a cracked stone tablet listing the names of everyone who has ever died trying to escape the maze.", "They find a pile of rusted armor stacked neatly beside a dry well, as though someone had been collecting it for years."],
    ["They meet Morpheus, god of dreams, who tries to lull the whole group to sleep so monsters can finish them off.", "They meet Nemesis, goddess of revenge, who blames Annabeth for past mistakes and demands she prove her worth before passing."],
    ["Dionysus appears, scolds Janus for wasting everyone's time, and hands the group a tray of grapes instead.", "Iris appears in a burst of rainbow light, tells Janus to knock it off, and offers to send a message to camp for them."],
    ["She hints that Tyson holds the key to their troubles because of his skill with metalwork, and tells them to visit the Cyclopes' forges.", "She hints that the answer lies with Chiron's centaur family somewhere in the wild, and tells them to seek out the wisest of his kind."],
  ],
  "pj-04-ch-07": [
    ["They find themselves inside a subway tunnel deep beneath Grand Central Station.", "They find themselves standing among the ruins of an old, buried coliseum."],
    ["They find Geryon's brother, a three-bodied giant who's been locked away for centuries after a failed rebellion against the gods.", "They find a captured satyr named Leneus, bitter and refusing to help because he blames Grover for losing his own search years ago."],
    ["Kampê is Kronos's personal bodyguard, a scorpion-tailed giant sent specifically to hunt down Percy and end the quest early.", "Kampê is a rogue Fury who abandoned the Underworld long ago and now guards the prison purely for her own twisted amusement."],
    ["Percy challenges Briares to an arm-wrestling contest using all hundred of his hands, and winning restores his confidence.", "Percy reminds Briares that Tyson is watching and would be ashamed of him for giving up, which shames him into standing up."],
    ["Annabeth throws her invisibility cap over Kampê's eyes, blinding her just long enough for the group to slip past into the tunnel.", "Percy summons a wave of seawater that floods the corridor, sweeping Kampê away while the group scrambles back into the maze."],
  ],
  "pj-04-ch-08": [
    ["Briares confesses that he's terrified of Kampê specifically because she once defeated him single-handedly centuries ago, leaving a scar he can't forget.", "Briares admits he doesn't trust Percy yet, worried that being a son of Poseidon means he'll eventually abandon his new friends like the gods once did."],
    ["They find one of Nico's black robes snagged on a jagged rock nearby.", "They find a trail of golden dust leading to a rusted iron grate."],
    ["They emerge into a dusty rodeo arena filled with monstrous bulls, guarded by a cowboy who turns out to be a minor son of Ares.", "They emerge onto a rocky cliffside overlooking the ocean, where a flock of harpies circles a half-built wooden fort."],
    ["Geryon is a towering giant with a single flaming eye who runs the ranch, and they find Grover there, disguised as one of the ranch hands.", "Geryon is Luke's personal enforcer, a former demigod twisted into a monster, and they find Rachel there, held captive as bait for Percy."],
    ["Percy agrees to wrestle Eurytion in single combat; if he wins, Nico goes free, but if he loses, Percy must join the ranch's workforce permanently.", "Percy agrees to hand over Riptide as payment for Nico's freedom, promising to retrieve it later once the quest is finished."],
  ],
  "pj-04-ch-09": [
    ["Percy recalls that Odysseus once tricked a cyclops into doing hard labor instead of doing it himself.", "Percy recalls a story Chiron told about Atlas being forced to hold up the stables' roof as punishment from Zeus."],
    ["The naiad happily agrees to help, diverting her entire river through the stables without asking for anything in return.", "The naiad demands a favor from Poseidon himself before she'll even consider helping Percy with the cattle mess."],
    ["Percy convinces Tyson to forge a giant magnet that pulls all the metal scraps and filth out of the stables at once.", "Percy uses Annabeth's architectural knowledge to build a system of ramps and pulleys that shovels the mess into the sea."],
    ["Geryon honors the deal completely, but Eurytion secretly attacks Percy anyway out of jealousy over losing his job.", "Geryon agrees to free Nico but insists on keeping Percy as a permanent ranch hand instead, sparking a fight over the terms."],
    ["Percy realizes Geryon's only weakness is a soft spot where his three bodies connect, and stabs him there with Riptide.", "Percy tricks Geryon into standing in a puddle of his own spilled cattle blood, which weakens him enough for Percy to finish him with his sword."],
  ],
  "pj-04-ch-10": [
    ["Nico buries a golden drachma and whispers a prayer to Hades, and the ghost of Bianca appears first, confused about where she is.", "Nico lights a small campfire and burns a lock of his own hair, and the ghost of Geryon appears, still furious about his defeat."],
    ["Minos warns Nico that Daedalus has already died for good this time and can never be summoned back.", "Minos warns Nico that Kronos plans to betray Luke the moment he's fully risen, so trusting him would be a mistake."],
    ["Bianca tells Nico that she's found peace in Elysium and asks him to stop trying to bring her back through any means.", "Bianca warns Nico that Eurytion secretly plans to betray the group the moment they leave the ranch."],
    ["Nico insists on continuing with the group all the way to Daedalus's workshop, and Grover finally admits he's given up hope of finding Pan.", "Nico vanishes into the shadows without a word, and Grover decides to abandon the quest to search for Pan on his own instead."],
    ["Eurytion hands Annabeth an old brass compass that always points toward Daedalus, and it leads them straight into a den of telekhines.", "Eurytion gives them directions scrawled on a napkin, and following them leads the group into a trap set by a group of dracaenae guards."],
  ],
  "pj-04-ch-11": [
    ["They meet Ares, the aggressive god of war, who mocks them for needing help and demands a fight before he'll cooperate.", "They meet Hermes, the quick-witted messenger god, who seems distracted and eager to get back to more important errands."],
    ["He wants Percy to retrieve a stolen hammer that Kronos's forces took from his forge years ago.", "He wants Annabeth to design blueprints for a new automaton army to help defend Olympus."],
    ["Grover and Tyson stay behind to guard the forge entrance instead.", "Grover and Tyson get pulled away by a sudden, violent earthquake."],
    ["They discover a nest of drakon eggs that Luke's forces have been incubating to raise an army of monsters.", "They discover Ethan Nakamura secretly stealing celestial bronze to sell to the highest bidder."],
    ["Percy grabs a nearby drainage pipe and floods the chamber with river water, sweeping the fire demons away before they can react.", "Percy prays to his father for help, and a sudden geyser bursts up through the volcano floor, launching him to safety."],
  ],
  "pj-04-ch-12": [
    ["He wakes up washed ashore on a beach near Camp Half-Blood, with Annabeth and Grover already hovering anxiously over him.", "He wakes up inside Poseidon's underwater palace, being tended to by a school of curious dolphins and his father's attendants."],
    ["She explains that Zeus banished her there for helping Kronos's forces during a battle centuries earlier.", "She explains that she chose to live there voluntarily after growing tired of the constant fighting among gods and mortals."],
    ["He must choose whether to trust Calypso's warning about a coming storm or to set sail immediately despite the danger.", "He must decide whether to reveal camp's location to Calypso, since she offers to help hide his friends from Kronos."],
    ["Percy decides to stay a little longer to recover his strength, and Calypso teaches him how to sail using magical winds.", "Percy tries to leave immediately, but Calypso's island magic won't let him go until he finishes a task she sets for him."],
    ["She asks him to carry a message to her sisters at camp, warning them that Atlas may soon break free.", "She hands him an enchanted bracelet and asks him to give it to Annabeth as a peace offering."],
  ],
  "pj-04-ch-13": [
    ["Camp is in the middle of a sudden evacuation drill for a possible attack.", "Camp is celebrating Percy's safe return with a bonfire that same night."],
    ["He learns Quintus was promoted to run the entire camp in Chiron's absence while the search for Percy continued.", "He learns Quintus revealed himself as a spy for Luke and fled camp just before being caught by Clarisse."],
    ["They've already returned safely, and Grover has been officially cleared of all wrongdoing by the Council.", "They're presumed dead by most campers, though Chiron insists on holding out hope a little longer."],
    ["Annabeth wants to abandon the quest entirely and wait for Daedalus to come to them instead, while Percy insists on pressing forward.", "Annabeth wants to bring Clarisse along as extra muscle, while Percy worries her temper will cause more problems than it solves."],
    ["Percy recruits Chris Rodriguez, a former follower of Luke's who knows the layout of Kronos's forces from the inside.", "Percy recruits his mother, Sally, since her mortal instincts once helped her sense monsters even without seeing through the Mist."],
  ],
  "pj-04-ch-14": [
    ["A band of telekhines ambushes them in the tunnels and drags them before Kronos's coffin for questioning about the quest.", "Dracaenae guards corner them near a dead end and hand them over to Kampê, who has tracked them since the prison escape."],
    ["Luke calls him that because Antaeus was once raised alongside Percy at Camp Half-Blood before defecting to Kronos's side.", "Luke calls him that only as a taunt, since Antaeus has no real family connection to Percy at all and it's meant to unsettle him."],
    ["Percy quickly beats Ethan, then convinces the crowd to release him anyway.", "Antaeus orders Percy to kill Ethan as proof of loyalty, but Percy refuses."],
    ["Percy realizes Antaeus can be worn down only by fire, so he has Grover create a wall of flame using stolen Greek fire.", "Percy discovers that Antaeus is vulnerable to seawater specifically, so he floods the arena floor until the giant can't get traction."],
    ["Rachel throws a hidden smoke bomb she'd been carrying, and the confusion lets the group slip out through a side tunnel.", "Annabeth negotiates their release by promising Antaeus safe passage through camp's borders once the war begins."],
  ],
  "pj-04-ch-15": [
    ["It collapses the tunnel behind them entirely, sealing off any way back and forcing them deeper into a flooded stone chamber.", "It opens a hidden staircase leading up into an abandoned subway station somewhere beneath Manhattan."],
    ["Quintus reveals that he's actually a minor god of blacksmiths sent by Hephaestus to test the group's worthiness.", "Quintus reveals that his hellhound, Mrs. O'Leary, is really an enchanted guardian left behind by Daedalus centuries ago to protect the workshop."],
    ["He admits he's been secretly feeding Chiron information about camp's defenses in exchange for his own safety.", "He admits he trapped the real Daedalus somewhere deep in the maze and has been impersonating him for years."],
    ["Grover arrives in chains, having been captured while searching for Pan, and uses his pipes to charm the monsters into retreating.", "Rachel arrives in chains after being kidnapped by telekhines, and uses a hidden dagger to cut herself free just in time."],
    ["The group escapes through a hidden elevator instead, riding it down into what turns out to be Geryon's ranch.", "The group is cornered by Kronos's forces and has to fight their way out through the workshop's front gates."],
  ],
  "pj-04-ch-16": [
    ["They crash-land in a cornfield somewhere in Kansas, and a curious farmer has to help them untangle the mechanical wings.", "They tumble into the middle of a crowded shopping mall food court, startling everyone with their sudden, clattering arrival."],
    ["She bribes a taxi driver with a fistful of drachmas, and Annabeth spots the mark carved into a highway overpass.", "She calls a family friend who happens to be a pilot, and together they spot the mark glowing faintly from the air."],
    ["He finds a locked iron cage holding a chained, snarling monster that looks like nothing he's ever seen before.", "He finds a massive stone throne carved with images of Kronos devouring his own children."],
    ["Inside is a pile of ash and a single golden coin, with no body at all, only a faint smell of sulfur still lingering in the cold morning air.", "Inside is an old, empty suit of Greek armor, rusted and clearly untouched for centuries, with no sign that anyone had ever been laid to rest there."],
    ["They gasp and whisper, 'The master returns soon,' while quickly resealing the coffin's lid and fleeing the hall.", "They laugh and mock Percy for opening it, saying, 'You've only sealed your own doom,' before vanishing into the shadows."],
  ],
  "pj-04-ch-17": [
    ["Grover has been searching for a way to break the curse trapping the satyrs' ancient forest home, hoping to finally free it.", "Grover has been searching for his long-lost satyr father, hoping to reunite their family before the coming war."],
    ["They find Pan disguised as an ordinary hiker, testing whether Grover could recognize him without any obvious clues.", "They find Pan trapped behind a wall of magical vines, weakened but still fighting to break free on his own."],
    ["Pan tells Grover the location of a hidden grove where the last of his power is stored, waiting to be claimed.", "Pan tells Grover to gather every satyr in the world and lead them in one final battle against Kronos's forces."],
    ["Pan transforms into a great stag and bounds off into the forest, promising to return once the war against Kronos ends.", "Pan is pulled away by a sudden burst of shadow, dragged back toward the Underworld before he can say another word."],
    ["Grover feels triumphant, certain that finding Pan will finally earn him the respect of the entire Council of Cloven Elders.", "Grover feels numb and confused, unsure whether what he witnessed was even real or just an exhausted hallucination."],
  ],
  "pj-04-ch-18": [
    ["They emerge inside Grand Central Terminal, where Hermes himself is waiting to hand them fresh supplies for the coming battle.", "They climb out through a manhole near the Empire State Building, where Chiron gallops up just in time with a squad of centaurs."],
    ["Grover announces that he's officially resigning as a satyr, since he no longer believes searching for Pan matters at all.", "Grover declares that Silenus should be removed from the Council immediately for wasting years chasing false leads."],
    ["Lightning strikes it during the chaos of battle, and Clarisse's cabin rushes over with buckets to douse the flames.", "It's trampled flat by a fleeing drakon, and Juniper has to be carried away before the tree can be saved at all."],
    ["They regroup and launch a second wave of attacks, forcing the campers to retreat deeper into the strawberry fields.", "They're routed by a surprise charge from the Hunters of Artemis, who arrive just in time to turn the tide of battle."],
    ["Percy says goodbye to Calypso, who appears briefly to see him off before returning to her hidden island.", "Percy says goodbye to Ethan Nakamura, who decides to strike out on his own instead of joining camp."],
  ],
  "pj-04-ch-19": [
    ["They congratulate Grover warmly and immediately promote him to the rank of Lord of the Wild.", "They demand physical proof of Pan's death before they'll even consider believing Grover's account."],
    ["Dionysus returns furious about losing a chariot race bet, still refusing to take the war against Kronos seriously.", "Dionysus returns triumphant, boasting about a minor victory his forces won against a group of stray monsters."],
    ["Dionysus sides firmly with the Council, arguing that satyrs can never be trusted to tell the truth about the gods.", "Dionysus refuses to vote at all, saying the whole trial is beneath his attention and storming out of the room."],
    ["The Council votes unanimously to exile Grover, and Chiron has to intervene personally to delay the punishment.", "The vote favors Grover overwhelmingly, and Silenus is forced to publicly apologize for doubting him."],
    ["He begins training to become the camp's official new sword instructor, giving up his satyr duties entirely.", "He begins quietly withdrawing from camp life altogether, unsure if he still belongs among the other satyrs."],
  ],
  "pj-04-ch-20": [
    ["Athena arrives to warn Percy that Annabeth's loyalty is being tested by a secret offer from Luke's side.", "Hermes arrives to deliver a birthday gift from the gods along with a cryptic warning about a coming betrayal at camp."],
    ["He realizes the sarcophagus actually held a decoy body meant to trick Kronos's enemies into thinking he had already returned.", "He realizes the body belongs to Ethan Nakamura, who was secretly given over to Kronos as a vessel instead of Luke."],
    ["Daedalus chooses to hand his workshop over to Quintus permanently, retiring from the Labyrinth forever.", "Daedalus chooses to flee into the mortal world, abandoning the Labyrinth for Kronos's forces to claim."],
    ["He spends the rest of the night quietly packing supplies, certain that Kronos's invasion will begin before morning.", "He spends the evening at the beach with Annabeth, too anxious about Typhon to think about celebrating at all."],
    ["He tosses it into the East River, deciding he's finished with quests and wants a normal life at last.", "He hands it to his mother for safekeeping, worried he might lose it during the battles still to come."],
  ],
  "pj-05-ch-01": [
    ["Grover Underwood, dressed in full satyr armor, crash-landed on Blackjack to warn Percy that monsters were closing in on camp. He'd flown all night carrying an urgent message from Chiron.", "Nico di Angelo, still pale from a trip through the Underworld, rode Blackjack down to tell Percy that Kronos's ship had changed course. He'd shadow-traveled halfway across the coast to catch up with him."],
    ["They snuck aboard to free a group of captured demigods rumored to be chained up somewhere belowdecks. It was risky because guards patrolled every corridor and the prisoners' exact location was unknown. Grover had overheard the rumor from a jumpy dryad near the docks and wasn't sure it could be trusted.", "They boarded to steal a map from Kronos's cabin that showed the location of every Titan army in the country. It was risky because Kronos rarely left his quarters unguarded even for a moment."],
    ["He froze the fountain solid with a burst of icy water, trapping the crab's legs in place before smashing its shell apart with the hilt of Riptide. The crab shattered into a thousand pieces and vanished. Percy's boots were soaked through by the time the fight ended.", "He lured the crab into snapping at its own reflection in the fountain's mirrored wall, tricking it into cracking its own claws against the glass. The crab crumbled apart from the impact and dissolved."],
    ["Kronos summoned a wall of solid gold armor around himself, so every one of Percy's strikes just bounced off harmlessly with a loud clang. Percy also lost his grip on Riptide when a sudden gust of wind knocked it from his hand. He scrambled to recover the sword before Kronos could press the advantage.", "Kronos split himself into three ghostly copies that surrounded Percy from every side, confusing him about which one was real. Percy also breathed in a cloud of golden dust that made his vision blur and his legs go weak."],
    ["He disguised himself as one of the ship's kitchen staff and calmly walked past the giants while carrying a tray of snacks, letting them assume he was just delivering food. This gave him just enough time to slip down to the engine room unnoticed.", "He hid the real explosives inside a crate stamped \"Toys for Tots\" and let the giants toss it aside without a second look, assuming it held nothing dangerous. This gave Beckendorf the extra minutes he needed to reach the detonator switch."],
  ],
  "pj-05-ch-02": [
    ["Percy woke up in the infirmary at Camp Half-Blood, where Chiron and Annabeth had been keeping watch over him. Annabeth explained that Blackjack had carried his unconscious body all the way back to camp.", "Percy woke up on the deck of a passing Coast Guard ship, where confused sailors had been trying to figure out where he'd come from. A sailor explained they'd pulled him from the water near Montauk that morning."],
    ["Tyson told Percy that Beckendorf had been spotted being dragged below deck by giants moments before the explosion went off. Percy felt sick imagining his friend being held prisoner somewhere on the sinking ship.", "Tyson told Percy that Beckendorf had washed up safely on a beach near Montauk, badly injured but alive. Percy felt a rush of relief mixed with guilt for leaving him behind on the ship."],
    ["A curse laid on him by a jealous Amphitrite had twisted his face into someone unrecognizable, and Poseidon begged Percy not to be frightened by it. He explained the curse would wear off once the war ended and peace returned to the sea.", "Poseidon had disguised himself as an elderly fisherman to sneak past Oceanus's spies patrolling the currents near his palace. He explained the disguise was the only way he could safely meet with Percy without being noticed. Percy almost didn't recognize him at first."],
    ["Triton is Poseidon's loyal dolphin messenger, a shapeshifting sea spirit who happily welcomed Percy and offered to guide him through the palace himself. He seemed thrilled that Poseidon's favorite son had finally come to help. He even offered to show Percy his private collection of sunken treasure from old shipwrecks.", "Triton is an enemy Titan who had infiltrated Poseidon's palace disguised as a merman, secretly reporting the palace's defenses back to Oceanus. He treated Percy with false friendliness to keep his cover from being blown."],
    ["Poseidon asked Percy to track down Triton and convince his prideful son to finally accept help from the other sea gods. Poseidon said the palace's defenses were crumbling because Triton refused to work with anyone else.", "Poseidon asked Percy to carry a message to Zeus, warning him that Oceanus was planning to attack the coastline near Olympus next. Poseidon said he couldn't leave his palace long enough to deliver it himself."],
  ],
  "pj-05-ch-03": [
    ["The whole camp erupted into celebration, certain the mission had been a total success now that the ship was gone. Even Clarisse cracked a rare smile and admitted the plan had gone better than she expected.", "Chiron immediately called an emergency meeting to ban Percy from ever going on another solo mission without permission. Annabeth argued furiously on Percy's behalf, insisting he'd done nothing wrong."],
    ["They were arguing over who should be given command of the next mission to track down Kronos's scattered forces. Both of them insisted their own cabin had earned the right to lead. Chiron had to step between them before it got physical.", "They were arguing about whose cabin had done the better job decorating the dining pavilion for the summer solstice. It felt petty and pointless given everything else going on at camp. Even Chiron looked embarrassed watching them argue about it."],
    ["They brought him to see a hidden map tucked behind an old trunk, one that revealed the exact location of Kronos's rebuilt fleet somewhere off the coast. It was something Chiron had kept hidden until he felt Percy was ready. Annabeth traced the coastline with her finger, already planning a strike.", "They brought him to meet a brand-new camper who had just been claimed, a son of Hecate with strange shadow magic. Chiron wanted Percy to see the boy's abilities before deciding whether he could be trusted."],
    ["The line about \"endless sleep\" made Percy worry that the whole camp was destined to be put under a magical curse forever, just like the mortals of Manhattan. He also worried the prophecy meant Chiron himself would fall in battle.", "The line about \"the eldest gods\" made Percy think his father, Poseidon, was fated to vanish completely once the war ended. He also worried it meant Olympus itself would crumble no matter what anyone did."],
    ["They saw Kronos's forces already constructing a second massive cruise ship somewhere off the Gulf Coast, preparing to finish what the Princess Andromeda had started. Chiron warned it could be ready to sail within the week. Annabeth guessed it would be even larger than the first ship.", "They saw the Empire State Building already crumbling into rubble, with panicked mortals fleeing through the streets below. Chiron warned that Olympus itself might already be lost by the time they could respond."],
  ],
  "pj-05-ch-04": [
    ["Rachel had painted a peaceful beach scene of a family vacation to St. Thomas that hadn't happened yet, along with a portrait of her father shaking hands with a stranger. Her father assumed it was just ordinary teenage daydreaming.", "Rachel had painted Chiron standing guard at the entrance to Camp Half-Blood, along with a picture of Percy and Annabeth sitting peacefully by the canoe lake. Her father thought the paintings looked oddly cheerful compared to her usual dark art."],
    ["They discovered a hidden tunnel underneath the Poseidon cabin that led straight down to an old, forgotten shrine. It made them wonder what other secrets the camp might still be hiding.", "They found out the Ares cabin had been quietly recruiting new campers from a nearby military school without telling Chiron. It made Percy suspicious that Clarisse was planning something behind everyone's back."],
    ["Percy mentioned that Poseidon wanted him to give up fighting and hide underwater until the war ended, and Annabeth accused him of running away from his responsibilities. It turned into a heated fight about loyalty and duty.", "Annabeth found out Percy hadn't told her the full contents of the Great Prophecy, and she felt betrayed that he'd kept it from her. She accused him of not trusting her enough to share something so important."],
    ["The camp burned a pile of old banners and worn-out training dummies to clear space for a new archery range. Nobody thought much of it beyond routine camp cleanup. Chiron mentioned it was long overdue, since some of the dummies were older than most of the counselors.", "The camp burned a small model replica of the Princess Andromeda to mark the ship's destruction and celebrate the successful mission. The fire crackled cheerfully, and campers cheered as it collapsed into ash."],
    ["She admitted her whole cabin was still recovering from injuries suffered in a recent skirmish and simply weren't fit to fight yet. Percy accepted her explanation, though he suspected there was more to the story.", "She demanded that Percy publicly apologize in front of the whole camp for something insulting he'd said the previous summer. Percy refused on principle, and the two of them stopped speaking to each other entirely."],
  ],
  "pj-05-ch-05": [
    ["He found Clarisse sitting alone by the woods, still fuming over the argument about the chariot and refusing to talk to anyone. Percy tried to comfort her, but she just told him to leave her alone. She warned him not to bring it up again if he wanted to keep all his fingers.", "He found Annabeth searching frantically through the woods for an old map of the Labyrinth she believed had been stolen. She asked Percy to help her track down whoever had taken it."],
    ["Nico said Beckendorf's spirit was furious and wandering restlessly through the Underworld, demanding revenge against Kronos before he could move on. It left Percy feeling even more guilty than before.", "Nico admitted he'd searched everywhere in the Underworld but had found no trace of Beckendorf's spirit at all, which worried him deeply. He wondered if something had gone terribly wrong with his soul's journey."],
    ["Nico revealed he had discovered the secret location of Kronos's rebuilt throne room somewhere deep beneath Manhattan. He believed sneaking in there was the only way to end the war quickly. He'd mapped out the tunnels himself using an old subway blueprint.", "Nico revealed that he suspected Chiron had been secretly passing information to the enemy for months. He believed exposing the betrayal was the real reason he'd been investigating all summer."],
    ["After hearing everything, Percy decided the risk was too great and told Nico he'd rather take his chances fighting Kronos the normal way. He asked Nico to keep the details of the plan a secret from everyone else.", "Percy told Nico he needed more time to think it over and wanted to talk to Annabeth before making such a big decision. He asked Nico to wait a few days before they discussed it again."],
    ["They flew there on the back of Blackjack the pegasus, cutting straight across Long Island Sound in the middle of the night. Blackjack grumbled the whole way about missing his usual doughnuts. He complained loudly the entire flight.", "They borrowed Paul's car from the garage and drove up the coast themselves, with Nico nervously giving directions from a crumpled map. It took most of the night to find the right neighborhood. Nico got them lost once along the way."],
  ],
  "pj-05-ch-06": [
    ["The house was completely abandoned, stripped bare of furniture, with newspapers piled up at the door dating back years. Nico explained that May Castellan had disappeared without a trace not long after Luke had left home. Even her mailbox had been sealed shut for years.", "The house was crammed floor to ceiling with weapons and armor she'd apparently gathered to fight off monsters herself. She greeted Nico and Percy calmly, clearly expecting them and already knowing exactly why they'd come. She even had a spear ready by the door."],
    ["She said Luke had come by needing money to buy a new sword, and she'd given him her savings without hesitation. She admitted she never saw him again after that visit.", "She said Luke had brought her a small gift from Camp Half-Blood as an apology for running away, and they'd spent the afternoon talking calmly. She remembered it as one of the happiest days of her life."],
    ["She suddenly remembered with perfect clarity exactly where Luke was hiding and calmly gave Percy detailed directions to find him. Just as quickly, the memory faded and she went back to baking cookies. Nico scribbled the directions down before she could forget them again.", "She collapsed from sheer exhaustion after baking dozens of batches of cookies in a row, muttering feverishly about needing everything ready before Luke came home. Nico had to carry her gently to a chair to rest."],
    ["Hestia turned out to be a camp counselor in disguise, checking up on Percy and scolding him sharply for sneaking off camp grounds without permission. She warned him he'd be in serious trouble once Chiron found out.", "Hestia was actually Annabeth's mother, Athena, in a hidden mortal disguise, quietly keeping watch over Percy's journey. She warned him that Annabeth's fate was tied closely to whatever choice he made. Percy found the idea hard to believe."],
    ["Sally flatly forbade Percy from attempting anything so dangerous and grounded him for even considering it, insisting there had to be a safer way. Percy had to sneak off later that night against her wishes.", "Sally insisted on coming along herself to protect Percy through the entire ordeal, packing a bag before he could argue. Percy eventually convinced her to stay behind only after a long, tearful conversation."],
  ],
  "pj-05-ch-07": [
    ["Percy used his empathy link to sense Grover camping out deliberately among the trees, hiding on purpose from monsters that had been hunting satyrs all summer. Grover explained he'd chosen to stay hidden until it was safe to come back.", "Percy used his empathy link to sense Grover trapped in a cocoon of vines grown by an angry dryad who blamed him for a forest fire. Grover explained the dryad had kept him prisoner there for weeks as punishment. He'd survived by nibbling on the vines themselves."],
    ["They caught a ride on Charon's ferry after finding it docked in the Los Angeles river, just like Percy had used on an earlier adventure. The trip took them the long way around through the western entrance to the Underworld. Charon grumbled the whole trip about exact change.", "Mrs. O'Leary dug straight down through the dirt with her enormous claws, tunneling deep beneath the park until she broke through into the Underworld. The three of them tumbled after her through the loose dirt and rock."],
    ["The Furies revealed that Nico had promised Hades he'd convince Percy to abandon the Olympians and fight for the Underworld's own army instead. Nico swore he'd never actually intended to go through with it.", "The Furies revealed that Nico had agreed to steal Riptide from Percy and hand it over to Hades as a show of loyalty. Nico insisted he'd only said it to buy time and never meant to follow through."],
    ["Hades explained that Nico and Bianca had actually been adopted by him after their real parents died in an accident, and they weren't truly his blood children at all. He admitted he'd kept this secret out of shame.", "Hades explained that their mother, Maria di Angelo, was actually still alive somewhere in the mortal world, living under a new name. He admitted he'd kept this from Nico to spare him the pain of her rejection."],
    ["Hades challenged Percy to single combat right there in the throne room, wanting to test whether he was truly strong enough to be worth helping. Percy had no choice but to accept the duel. Nico begged his father to reconsider, but Hades refused to back down.", "Hades sent Percy back to camp immediately with a stern warning never to return to the Underworld uninvited again. Percy left frustrated, having gained nothing from the long journey."],
  ],
  "pj-05-ch-08": [
    ["Achilles warned Percy that he could never draw Riptide again after entering the river, or the curse would instantly unravel and kill him. He also admitted he regretted ever giving Luke that same warning years before. He said the guilt of it had haunted him ever since.", "Achilles warned that only demigods born after a certain sacred year could survive the river's power at all, and Percy might not qualify. He also admitted he wasn't sure the ritual had ever actually worked on anyone before."],
    ["Percy chose his left shoulder, the spot where an old scar from a past battle still ached faintly. When the pain became unbearable, he held onto a memory of his mother singing to him as a small child. The scar throbbed the entire time he was submerged.", "Percy chose the back of his neck, just below his hairline, since it felt like the safest place to hide a weakness. When the pain became unbearable, he held onto the sound of Grover's reed pipes playing a calming song."],
    ["Percy immediately collapsed from exhaustion and had to be dragged out of the cavern by Mrs. O'Leary before he could even stand. It took him hours to recover enough strength to speak. Nico stayed by his side the whole time, worried sick.", "Kronos himself appeared in Luke's body, hoping to finish Percy off while he was still weak from the ritual. Percy barely managed to escape by diving back into the river's current."],
    ["Percy and Hades shook hands and struck a tense truce, agreeing to set aside their differences until Kronos was defeated. It was an uneasy alliance neither of them fully trusted. Nico watched nervously, half-expecting it to fall apart.", "Hades apologized for locking Percy up earlier and released him from his imprisonment without any further argument. He even offered Percy a small army of skeleton warriors as an apology."],
    ["Percy told Nico to stay hidden safely in the Underworld until the entire war was completely over, worried the surface world was too dangerous for him now. Nico reluctantly agreed to wait it out. Nico grumbled about missing all the action.", "Percy told Nico to warn Chiron that Hades could never be trusted again after everything that had happened. Nico promised to deliver the warning as soon as he reached camp. He also asked Nico to watch the borders."],
  ],
  "pj-05-ch-09": [
    ["Chiron admitted he was still recovering from wounds suffered in an earlier skirmish and wasn't strong enough to make the climb up to Olympus yet. He asked Annabeth to lead the campers in his place. He hated admitting the weakness out loud.", "Chiron confessed he no longer fully trusted the campers after the spy scandal and preferred to stay behind and guard camp personally. He left Percy in charge only reluctantly, still suspicious of everyone's loyalty."],
    ["Ares appeared instead, cheerfully offering to personally lead the defense of the city himself, eager for a good fight. He assured the campers that with him in charge, victory was practically guaranteed.", "Nobody came to greet them at all, and the campers stood alone in the empty throne room, unsure what to do next. The silence made everyone feel like they'd been completely abandoned. Even Annabeth looked shaken by the emptiness."],
    ["Hermes was furious that Annabeth had misplaced his prized winged sandals during an earlier mission and demanded she replace them immediately. Annabeth apologized, confused about why he was so upset over something so small.", "Hermes accused Annabeth of secretly stealing his caduceus staff to use as a weapon against Kronos without his permission. Annabeth denied it firmly, insisting she'd never touch something so dangerous."],
    ["Hestia showed him a vision of Beckendorf, somehow still alive, hiding out quietly in a cabin somewhere upstate. Percy felt a jolt of hope that maybe his friend hadn't really died after all. He nearly rushed off right then to go find him, before Hestia gently stopped him.", "Hestia showed him the exact hideout where Kronos's remaining forces were regrouping, tucked away in the woods of New Jersey. Percy immediately wanted to rush off and attack before the vision even finished."],
    ["Looking out over the city, they realized the streets below had been completely evacuated by the police in an unusual, coordinated operation. It seemed like someone had warned the mortals just in time. Annabeth wondered aloud who could have pulled that off.", "Looking toward Midtown, they realized the Empire State Building itself had already begun crumbling into rubble before the fighting had even started. It looked like the battle had somehow started without them."],
  ],
  "pj-05-ch-10": [
    ["She used an old brass telescope she found tucked away in the Big House attic, one that had supposedly belonged to a long-forgotten hero. It let her spot movement along the distant bridges, though the image was blurry and unreliable.", "She borrowed a pair of ordinary binoculars from a nearby camera shop, scanning the horizon from the rooftop of the Empire State Building. It let her catch glimpses of monsters moving through the streets below, though only up close."],
    ["He kept every single camper together in one large group stationed permanently at the base of the Empire State Building, like the Apollo cabin and the Demeter cabin standing shoulder to shoulder. He worried that splitting up the defenses would leave any one crossing point too weak.", "He sent most of the campers back to Camp Half-Blood, deciding it was safer to protect their home base, though he did leave the Apollo cabin behind to watch the Williamsburg Bridge alone. Only a handful of volunteers stayed behind in the city. Chiron worried privately it left the city undefended."],
    ["It turned out to be a hidden code word that, once spoken, would instantly summon Zeus himself down from Olympus to help. Annabeth said the phrase aloud, but nothing seemed to happen right away. She tried it twice more, growing increasingly frustrated.", "It turned out to be a secret escape tunnel running beneath the city, meant to evacuate campers if the fighting went badly. Annabeth found the entrance hidden inside a subway maintenance closet."],
    ["He challenged both river gods to an underwater wrestling match, and after defeating them fairly, he earned their respect and their help for free. They agreed to fight for him without asking for anything in return. Percy came up gasping and bruised, but victorious.", "He promised to personally introduce them to Poseidon at a future feast if they lent their strength to the fight. They accepted eagerly, delighted at the thought of meeting the great sea god himself."],
    ["She told him that Clarisse had finally shown up with the entire Ares cabin, ready to fight after all. It meant the campers finally had the reinforcements they desperately needed. Percy nearly cheered out loud at the news.", "She told him that Rachel had just arrived safely at the Empire State Building, having somehow slipped past the mortal barricades. It meant one less thing for Percy to worry about."],
  ],
  "pj-05-ch-11": [
    ["Percy tricked the Minotaur into charging blindly off the edge of the bridge by himself, using a clever feint that fooled the beast completely. It ended the fight without Percy needing to land a single blow. The beast bellowed all the way down.", "Annabeth distracted the Minotaur from behind while Percy snuck around and stabbed it through its unprotected back. Together they worked in perfect coordination to bring the huge beast down. It was a plan they'd practiced only once before, in training."],
    ["Percy spotted Beckendorf himself riding among the enemy forces, somehow alive and now apparently working for Kronos. It was a devastating shock that nearly made Percy freeze up in battle. For a moment he couldn't even lift his sword.", "Percy spotted Chris Rodriguez, Clarisse's boyfriend who had once betrayed the campers, charging with the enemy riders once again. It brought back painful memories of an earlier betrayal."],
    ["Grover blocked the blow at the last second using his reed pipes, deflecting the strike harmlessly to the side. Percy was grateful but puzzled how Grover had known exactly where to aim. Grover just shrugged and said satyrs notice everything.", "The strike missed completely, sliding off Percy's skin without leaving a mark, since his new invincibility seemed to protect him absolutely everywhere. Percy assumed the ritual must have made him fully immune to harm."],
    ["He asked the river gods to flood the entire bridge deck, washing Kronos's army straight off into the water below. The soaked and battered monsters scrambled back in a chaotic retreat. Percy had to hold on tight to keep from being swept away himself.", "He convinced the arriving Party Ponies to charge straight into the enemy lines, scattering Kronos's forces before they could regroup. The centaurs' surprise attack forced a hasty retreat across the river. Chiron led the charge himself, guns blazing."],
    ["Michael Yew was spotted flying safely back toward camp on a borrowed chariot, waving triumphantly at the exhausted campers below. Everyone cheered, relieved that he'd made it out unharmed. He even did a little victory loop before landing.", "Michael Yew called Percy's cell phone moments later to report that he was fine and had simply gone to check on the Apollo cabin's other archers. Percy felt a wave of relief at the unexpected call."],
  ],
  "pj-05-ch-12": [
    ["He told her he was seriously considering accepting the gods' earlier offer of immortality once the war finally ended. Annabeth admitted she didn't know how to feel about him possibly becoming a god.", "He told her that Beckendorf's ghost had visited him in a dream the night before, warning him about a coming betrayal. Annabeth admitted the dream unsettled her as much as it did him. Neither could shake the feeling that morning."],
    ["She admitted that she had secretly passed information to Luke for years, acting as a hidden spy inside camp without anyone realizing it. She confessed the guilt of that betrayal had been eating at her ever since.", "She admitted that Luke had once tried to steal her magical invisibility cap during a training exercise years earlier, and she'd never fully trusted him since. She said that moment was when she first started doubting him."],
    ["He reported that every single satyr defending the city had abandoned their post and fled back to the wild in fear. It left the campers without any of the extra help they had been counting on.", "He said that Juniper and several other nymphs had been captured by enemy forces near the edge of the park. It meant Grover now had two separate crises to worry about."],
    ["He saw that the Oracle itself had chosen, out of exhaustion, to never speak through a new host again after giving one final, terrible prophecy. It was a decision made entirely on its own, with no god involved.", "He saw that Zeus had destroyed the Oracle's ability to pass to a new host out of jealousy over its growing influence. It was a punishment meant to keep the gods firmly in control of prophecy. Percy found the idea unsettling."],
    ["Rachel discovered she could suddenly understand and speak with animals, and sensing that Percy was in trouble, she used a nearby hawk to send an urgent warning racing ahead to her father. It showed powers she never knew she had. She'd never even liked birds before.", "Rachel found an old, hidden treasure map tucked inside one of her own paintings, and sensing that Percy needed her, she used it to bargain with her reluctant father for an immediate ride home. It was a strange, lucky coincidence that got her back just in time. She still isn't sure how she found it in time."],
  ],
  "pj-05-ch-13": [
    ["Ares himself arrived under the truce flag, demanding the campers hand over their weapons immediately or face total destruction. Percy laughed off the threat and refused to even consider it. Even Clarisse looked embarrassed by him.", "Luke himself arrived alone under the truce flag, asking quietly to speak with Percy without Kronos listening in. Percy agreed cautiously, though he suspected it might be a trap. Annabeth insisted on standing close by, just in case."],
    ["He explained that Kronos himself had personally rescued him from a deadly monster attack when he was just a small child, earning his lifelong loyalty. It made his devotion to the Titan lord feel almost understandable. Percy wasn't sure whether to believe the story.", "He explained that he'd lost his eye the previous summer fighting alongside Percy against a group of giants near camp. It made his current betrayal feel even more shocking to hear. Percy remembered that fight vividly."],
    ["Percy saw a triumphant vision of Kronos being utterly defeated and sealed away by the original generation of Olympian gods. It was meant to remind Percy just how powerful the Titans truly were. The image looped over and over, as if daring Percy to give up.", "Percy saw a painful vision of Beckendorf's final moments aboard the Princess Andromeda, forced to watch the explosion happen all over again. It left him shaken and furious at Prometheus for showing it to him."],
    ["He gave Percy a detailed map marking every single hideout used by Kronos's scattered forces across the country. He said Percy could use it to hunt down and destroy the enemy once and for all. The ink seemed to shimmer faintly, like it was alive.", "He gave Percy a magical shield forged by Hephaestus that could block absolutely any weapon, even a god's. He said it was meant to help Percy survive the coming battle for Olympus."],
    ["A sudden fight broke out despite the truce, and Percy chased Prometheus and his escort off camp grounds entirely. It left the campers feeling like they'd won a small victory before the real battle even began.", "Prometheus, moved by Percy's arguments, unexpectedly agreed to switch sides and help the campers fight against Kronos instead. It gave the campers a surprising and welcome new ally. Even Chiron seemed skeptical it would last."],
  ],
  "pj-05-ch-14": [
    ["The battle moved to the lobby of the Empire State Building, where Percy suddenly found himself face-to-face with Kronos himself. Percy summoned every ounce of his water power just to hold his ground. The marble floor cracked beneath their feet as they clashed.", "The battle moved to the Brooklyn Bridge, where Percy confronted an entirely new army of giants that had crossed over from Long Island. Percy called on the river gods to help hold the line."],
    ["They convinced Hyperion, through clever flattery about his own greatness, to switch sides and fight for the campers instead. It was a surprising and welcome change of allegiance. Even Grover seemed shocked it actually worked.", "They doused him repeatedly with jars of Greek fire until the flames finally overwhelmed him and forced him to retreat. It was a risky, fiery way to drive off a Titan."],
    ["He sent an entire fully armored legion of skeleton warriors marching up from beneath the park's reservoir. It caused the campers to scatter in a chaotic, disorganized retreat.", "He sent Typhon himself early, hoping the giant monster would reach New York before the gods could stop him. It caused the campers to panic, believing all hope was already lost."],
    ["He lured the sow into diving straight into the East River, where the river god he'd befriended earlier dragged it under and drowned it. Blackjack circled overhead, cheering him on the whole time.", "He used Riptide to slice off both of its enormous wings mid-flight, sending it crashing helplessly to the ground below. Blackjack swooped in afterward to finish it off. Feathers rained down over three city blocks."],
    ["Kronos openly admitted, almost proudly, that Luke's mind had been completely erased and would never resurface again. It seemed to confirm Percy's worst fears about his old friend. Percy felt something inside him go cold.", "Kronos casually revealed the exact location of Percy's one weak spot, taunting Ethan about how easily the war could be won now. It left Percy terrified that his secret was no longer safe."],
  ],
  "pj-05-ch-15": [
    ["Poseidon himself arrived in person, rising from the reservoir to fight alongside the campers with a trident crackling with lightning-blue energy. His sudden appearance turned the tide of the battle instantly.", "Clarisse finally arrived leading the entire Ares cabin, electric spears crackling as they charged into the fight. Everyone cheered, relieved that the missing reinforcements had shown up at last."],
    ["Chiron reported that Typhon had already defeated Zeus completely and seized control of Mount Olympus for himself. It made the war in New York feel almost pointless by comparison. Percy refused to believe such news could be true.", "Chiron reported that Typhon had smashed straight through Poseidon's undersea palace, forcing Percy's father to retreat entirely. It meant Percy might soon lose contact with his father altogether."],
    ["Dionysus warned that the campers' only real chance was to surrender immediately, insisting that continuing to fight would only get more of them killed. It was a bleak, discouraging message to receive. Even Chiron looked troubled by the warning.", "Dionysus warned that Percy's mother back home was in serious danger and urged him to abandon the fight to go check on her right away. It left Percy torn between his duty and his family."],
    ["He found a hidden note tucked under the seat, written in Luke's handwriting, warning him about a trap waiting somewhere near Olympus. Chiron said the note's origin was a total mystery. The paper looked old and worn.", "He found Blackjack curled up asleep in the backseat, having apparently hidden there the whole time to avoid the chaos outside. Chiron laughed, saying even pegasi needed a break sometimes."],
    ["Rachel arrived calmly riding on the back of a hippocampus that Percy had summoned earlier, cutting straight up the river to reach them. She stepped off looking completely unbothered by the chaos around her.", "Rachel simply walked in through the front doors of the Plaza Hotel, having slipped past the mortal barricades using a clever disguise. She acted as if arriving in the middle of a warzone were the most normal thing in the world."],
  ],
  "pj-05-ch-16": [
    ["Percy used his water powers to gently slow the helicopter's fall, cushioning it with a controlled updraft until it touched down safely. It was an impressive display of his growing control over the elements.", "Chiron flew up on his own and physically towed the helicopter down using ropes tied to his powerful centaur body. It was an exhausting, awkward rescue that left him gasping for breath afterward."],
    ["She warned him that Annabeth had secretly been passing information to Luke this entire time and couldn't be trusted anymore. Percy refused to believe it, though the warning shook him.", "She warned him that Chiron was quietly planning to abandon the city and retreat all the way back to camp. Percy found the idea hard to believe given everything Chiron had already sacrificed."],
    ["The Minotaur returned for a furious second attack on the exhausted campers, and Rachel sensed it would finally be destroyed by \"a child of Poseidon.\" Percy realized with dread that meant the fight was his alone. His stomach sank at the thought.", "The Clazmonian Sow came back seeking revenge after its earlier defeat, and Rachel sensed it would be stopped by \"a trick of iron and fire.\" Nobody was quite sure yet what that clue actually meant."],
    ["Annabeth, wearing borrowed Ares armor to catch the drakon off guard, led the charge and was struck by a poisonous spray that knocked her to the ground. Percy rushed to her side, terrified she might not survive.", "Thalia, who had swapped armor with Clarisse as part of a planned trick, led the charge and was badly wounded by a burst of venom to the face. The Hunters of Artemis cried out in alarm at seeing their leader fall."],
    ["When the helmet came off, it turned out to be Rachel Dare, who had secretly slipped into the fight without anyone noticing. Clarisse showed up moments later and finished off the drakon with a lucky spear thrust. Percy could hardly believe his eyes.", "When the helmet came off, everyone was stunned to see Ethan Nakamura, who had apparently switched sides to help the campers. Clarisse arrived afterward and delivered the final blow that destroyed the drakon."],
  ],
  "pj-05-ch-17": [
    ["She confessed that Clarisse had convinced her to wear the disguise as part of a harmless prank that had gone terribly wrong. She died moments later, apologizing to Clarisse for the mix-up. Clarisse broke down sobbing, insisting it was all her fault.", "She confessed she had been secretly planning all along to abandon Kronos and switch back to helping the campers before it was too late. She died moments later, relieved that she'd finally made the right choice. Percy squeezed her hand until the very end."],
    ["Clarisse quietly retreated back to camp, too devastated by the loss to keep fighting alongside the others. Chris Rodriguez went with her, worried about how deeply the grief had shaken her. He kept a careful distance, unsure what to say.", "Clarisse blamed Percy directly for failing to protect Silena and refused to speak another word to him for the rest of the battle. Chris Rodriguez tried to calm her down, but she wouldn't listen."],
    ["She admitted that she was seriously considering giving up her dream of architecture entirely to become a full-time warrior instead. It surprised Percy, since he'd never seen her doubt her calling before. He tried to talk her out of it right away.", "She admitted she had actually known about Silena being the spy for weeks and had chosen to keep it secret to protect her. Percy was stunned that she'd carried that burden alone for so long."],
    ["Percy opened the jar right there out of sheer curiosity, wanting to know exactly what would happen if Hope were finally released. Nothing dramatic seemed to occur, though he felt strangely calmer afterward.", "Percy threw the jar into the Hudson River, hoping to be rid of its burden for good rather than carry it any further. He watched it sink and disappear beneath the murky water."],
    ["He asked Poseidon to make him an immortal god right then and there, wanting to end the war with power to match Kronos. Poseidon gently refused, saying the choice wasn't his to make alone. Percy looked stunned by his own request.", "He asked Poseidon to send Tyson home immediately to keep him safe from the fighting in Manhattan. Poseidon agreed at once, glad to have one less thing to worry about."],
  ],
  "pj-05-ch-18": [
    ["Chiron single-handedly defeated Kronos in a fierce duel, ending the battle much earlier than anyone expected. The campers cheered, believing the war was suddenly over. Someone even started singing in celebration.", "Chiron retreated safely once his supply of paintball arrows ran out, pulling his centaur army back to regroup at the edge of the park. He promised to return once they'd resupplied."],
    ["Poseidon arrived rising from a nearby fountain with an army of Cyclopes and mermen, ready to defend Olympus at last. Percy felt a surge of relief seeing his father finally join the battle. The fountain's water glowed a brilliant sea-green as they emerged.", "Chiron's centaur army returned with fresh reinforcements gathered from every state in the country, thundering back into the fight. Their numbers had nearly doubled since they'd left to regroup."],
    ["He collapsed the entire elevator shaft with a single blow, making sure absolutely no one could reach Olympus by any means. It seemed to seal their fate completely. Dust and twisted metal rained down for several long minutes.", "He turned the whole building invisible to mortal eyes so that nobody outside could witness or interfere with the coming fight. It left Percy's group fighting in total secrecy. Even the police outside forgot the building existed."],
    ["Paul and Sally stayed safely hidden inside their locked car the entire time, watching the battle unfold from a distance. They were relieved when it was finally over and they could drive home. Sally kept a tight grip on Paul's hand the whole time.", "Paul and Sally flagged down a passing police car and insisted the officers handle the monsters instead of getting involved themselves. They watched anxiously from the sidewalk as the fight raged on."],
    ["He asked her to guard his parents at the edge of the magical barrier while he went ahead alone to confront Kronos. Mrs. O'Leary whined but obeyed, planting herself protectively beside Sally and Paul.", "He asked her to carry Silena's shroud safely back to camp so it could be properly honored during the funeral rites. Mrs. O'Leary took off at a run, determined to complete the sad task."],
  ],
  "pj-05-ch-19": [
    ["He knocked Kronos's scythe straight into the hearth fire, melting the weapon instantly and leaving Kronos unarmed for a moment. It gave Percy a brief window to regroup with his friends. Smoke curled up from the melted blade.", "He convinced Kronos to duel Annabeth instead so that he himself could catch his breath and recover some strength. Annabeth reluctantly agreed, buying Percy the time he desperately needed."],
    ["Ethan refused outright to fight at all, simply turning and walking away from the throne room without another word. Kronos let him go, seemingly uninterested in punishing him. Percy thought he saw a flicker of doubt cross Ethan's face.", "Ethan lunged at Percy exactly as ordered but missed by pure accident, his blade clattering harmlessly across the marble floor. Kronos screamed in fury at the failed attack and shoved Ethan aside."],
    ["Grover's desperate music finally broke through whatever spell had been holding Luke's mind prisoner inside his own body. Luke blinked, suddenly aware, and looked around in confusion. He seemed to recognize Percy for the first time in ages.", "A strange potion Chiron had slipped into Luke's water earlier finally took effect, instantly restoring his mind and pushing Kronos out. Luke gasped and clutched his head as the change took hold."],
    ["Percy chose to throw the knife into the hearth fire instead of using it at all, unwilling to trust anyone with such a dangerous choice. It left everyone unsure how the fight could possibly end. Annabeth shouted in protest, but it was already done.", "Percy chose to strike Kronos himself while Luke was momentarily distracted, refusing to risk handing over the only weapon that could work. It was a split-second decision made entirely alone."],
    ["Luke tricked Kronos into stumbling backward into the hearth fire, which destroyed the Titan instantly while Luke himself escaped completely unharmed. He walked away quietly afterward, saying little to anyone.", "Luke managed to defeat Kronos in the fight but was badly injured, so he flew off on a borrowed pegasus to recover somewhere in secret. Nobody saw him again for the rest of the book. Percy always wondered what became of him."],
  ],
  "pj-05-ch-20": [
    ["He realized it meant Riptide itself would eventually have to be destroyed forever to prevent anyone from misusing it the way Kronos had. It made him wonder if he'd have to give up his sword someday. The thought made him grip Riptide tighter.", "He realized it meant Kronos's own scythe was fated to one day be used to kill an Olympian god in some future war. It left Percy with an uneasy feeling about what might still be coming. He couldn't shake the feeling for days."],
    ["He asked for a huge display of fireworks to be set off over the entire city in celebration of the victory. Zeus obliged, and the sky above Manhattan lit up in dazzling colors.", "He asked Zeus to send a personal message directly to Rachel's family, letting them know she was safe after everything that happened. Zeus grumbled but agreed to pass along the message."],
    ["Annabeth was made an immortal goddess on the spot, while Grover was handed Poseidon's trident to guard for safekeeping. Both of them looked completely stunned by the sudden honors. Neither of them knew quite how to react at first.", "Annabeth was sent to help guard the entrance to the Underworld as a reward, while Grover was made a general among the Party Ponies. Both accepted the strange honors with a mix of pride and confusion."],
    ["Percy accepted the offer immediately without a second thought, becoming the newest god on Olympus right there in the throne room. The gods erupted into applause at his quick decision.", "Percy asked instead to be crowned king of the Cyclopes, wanting a position of power among his father's other children. The gods exchanged puzzled looks at such an unusual request. Even Poseidon looked baffled by the idea."],
    ["He asked that Camp Half-Blood be relocated somewhere far from New York, believing the city had become too dangerous for young demigods. The council debated the idea but ultimately left camp exactly where it was.", "He asked that Kronos's scattered essence be tracked down and destroyed completely so there would be no chance of him ever returning. The gods admitted such a thing might not even be possible. Some of them doubted it could ever truly be finished."],
  ],
  "pj-05-ch-21": [
    ["He explained that Kronos had been captured and would be imprisoned once again deep in Tartarus, this time under much heavier guard than before. It gave Percy some comfort that the Titan was truly contained.", "He explained that Kronos had genuinely been destroyed for good this time, with no possible way for him to ever come back. Percy felt a wave of relief hearing the news confirmed."],
    ["He asked Percy to personally adopt one of his own unclaimed children and raise the kid himself at Camp Half-Blood. Percy was taken aback by such an unusual and heavy request. Percy wasn't sure how he'd even explain that to his mom.", "He asked Percy to keep the whole list of unclaimed demigods a secret from Chiron for reasons he wouldn't explain. Percy found the secrecy strange and a little unsettling."],
    ["She thanked him warmly for his service and offered him a permanent seat of honor on Olympus alongside the other gods. Percy was surprised by how kind and approving she seemed.", "She ignored him completely, walking straight past without acknowledging his presence at all. Percy was left standing there, unsure what to make of the cold silence. Even Annabeth seemed puzzled by the snub."],
    ["He reunited unexpectedly with Beckendorf, who it turned out had somehow survived the ship explosion after all. Percy could hardly believe his eyes and hugged his friend in disbelief. The two of them laughed and cried at the same time.", "He reunited with Silena Beauregard, who had miraculously recovered from her injuries overnight. Percy was overjoyed to see her walking and smiling again. Clarisse hugged her so hard she nearly fell over."],
    ["He rushed in to report that Kronos's scattered dust had already begun reforming somewhere deep underground. It left everyone terrified the war might start all over again.", "He rushed in to report that Clarisse had been badly injured in a final skirmish and needed help right away. Percy dropped everything to go check on her. He sprinted the whole way there without stopping."],
  ],
  "pj-05-ch-22": [
    ["They borrowed a car from a friend and drove straight up the highway through the night, taking turns behind the wheel. It was a long, exhausting drive to reach camp in time. They stopped only once for gas.", "They flew together on the back of Mrs. O'Leary, who could somehow shadow-travel long distances when she was well rested. It was a strange, bumpy ride across the state."],
    ["Rachel decided to enroll at Camp Half-Blood as a full-time camper instead of returning to her old life, wanting to stay close to her friends. Percy was thrilled at the unexpected news. Chiron welcomed the idea warmly.", "Rachel challenged Clarisse to a friendly duel to prove to everyone that she truly belonged among the campers. Clarisse accepted, grinning, and the two of them sparred good-naturedly. Percy watched nervously from the sidelines."],
    ["In a calm, steady voice, she repeated the old prophecy line \"A single choice shall end his days,\" as though reminding everyone it still applied. She remembered every word of it clearly afterward. Chiron looked troubled hearing it again.", "In a strange, tripled voice, she predicted the exact date Kronos would rise again to attack the camp a second time. She remembered the prediction vividly and repeated it several times. The whole cabin fell silent listening to it."],
    ["It turned out Percy was actually turning seventeen instead of sixteen, since he'd lost track of time during his stay in the Underworld. Annabeth teased him for not even knowing his own age. Percy insisted the Underworld had messed with his internal calendar.", "It turned out Percy shared his exact birthday with Grover, something neither of them had ever realized before. They laughed about it and decided to celebrate together from then on."],
    ["The two of them had a big argument about the new prophecy and didn't speak to each other again for the rest of the night. Percy went to bed feeling frustrated and confused. Neither one apologized before they went their separate ways.", "The two of them solemnly announced to the gathered campers that they'd both decided to leave Camp Half-Blood for good. Everyone fell silent, stunned by the unexpected news. A few younger campers even started crying at the news."],
  ],
  "pj-05-ch-23": [
    ["The camp was shrinking noticeably because so many campers had decided to leave for good after the hard losses of the war. It left everyone feeling a little more anxious about the future. Even the dining pavilion felt emptier at every meal.", "The camp was being relocated to a brand-new site somewhere outside New York, since the old grounds were considered too exposed after the invasion. Campers spent the summer packing up their cabins."],
    ["Poseidon asked Percy to move permanently into his undersea palace, arguing it would finally be safe enough for him there. Percy politely declined, saying he wasn't ready to leave the surface world. Poseidon looked disappointed but understood.", "Poseidon mentioned that Triton would be coming to visit camp very soon to get to know his half-brother better. Percy wasn't sure how he felt about that particular reunion. He hoped Triton would at least try to be civil."],
    ["It showed a picture of the Princess Andromeda exploding at sea, marking the mission that had started the whole war's final chapter. Campers wore it proudly as a badge of the summer's biggest victory.", "It showed Rachel's face, honoring her as the new Oracle who now watched over the camp's prophecies. It felt like a fitting tribute to her new, important role."],
    ["Both girls decided to stay at Camp Half-Blood all year round, choosing not to return to the mortal world at all, since Chiron said it was finally safe enough for that. Percy was glad to know they'd both be close by through the winter. It felt like the happiest ending anyone could have hoped for.", "Rachel and Annabeth were both moving away together to attend the same boarding school out in California, packing up their things the very same week. Percy felt a pang of sadness knowing they'd both be so far from camp and from him."],
    ["The book ends with Percy finally accepting the gods' old offer of immortality after realizing he couldn't imagine life without Annabeth by his side. The two of them walk up to Olympus together one last time. Chiron watches them go, smiling for the first time in weeks.", "The book ends with Kronos's scattered essence suddenly reforming near Half-Blood Hill, forcing the camp into one final battle. Percy and Annabeth race to grab their weapons one more time, refusing to let the war start over again."],
  ],
};

export default percyJacksonDistractors;
